// src/api/runtime.js
(() => {
  function createApiRuntime(deps = {}) {
    const getWindow = typeof deps.getWindow === "function" ? deps.getWindow : () => window;
    const createRequestError = typeof deps.createRequestError === "function"
      ? deps.createRequestError
      : (message, details = {}) => Object.assign(new Error(message), details);
    const safeStorageRemove = typeof deps.safeStorageRemove === "function" ? deps.safeStorageRemove : () => {};
    const sessionKey = String(deps.sessionKey || "winga-current-user");
    const csrfRuntime = {
      token: "",
      promise: null
    };

    function bindAbortSignal(controller, externalSignal) {
      if (!controller || !externalSignal || typeof externalSignal.addEventListener !== "function") {
        return () => {};
      }
      if (externalSignal.aborted) {
        try {
          controller.abort();
        } catch (_error) {
          // Ignore duplicate abort attempts.
        }
        return () => {};
      }
      const forwardAbort = () => {
        try {
          controller.abort();
        } catch (_error) {
          // Ignore duplicate abort attempts.
        }
      };
      externalSignal.addEventListener("abort", forwardAbort, { once: true });
      return () => {
        try {
          externalSignal.removeEventListener("abort", forwardAbort);
        } catch (_error) {
          // Ignore listener cleanup failures.
        }
      };
    }

    function emitApiMetric(detail) {
      const targetWindow = getWindow();
      if (typeof targetWindow === "undefined" || typeof targetWindow.dispatchEvent !== "function" || typeof targetWindow.CustomEvent !== "function") {
        return;
      }
      try {
        targetWindow.dispatchEvent(new targetWindow.CustomEvent("winga:api-metric", { detail }));
      } catch (_error) {
        // Metrics must never block the user path.
      }
    }

    function getApiEndpointLabel(url) {
      try {
        const targetWindow = getWindow();
        const parsedUrl = new URL(String(url || ""), targetWindow.location?.origin || "https://wingamarket.com");
        return parsedUrl.pathname.replace(/^\/api\//, "/");
      } catch (_error) {
        return String(url || "");
      }
    }

    function isUnsafeApiMethod(method = "GET") {
      return ["POST", "PUT", "PATCH", "DELETE"].includes(String(method || "GET").toUpperCase());
    }

    function getCsrfTokenUrl(url) {
      const targetWindow = getWindow();
      const parsedUrl = new URL(String(url || ""), targetWindow.location?.origin || "https://wingamarket.com");
      const parts = parsedUrl.pathname.split("/");
      const apiIndex = parts.indexOf("api");
      if (apiIndex >= 0) {
        parsedUrl.pathname = `${parts.slice(0, apiIndex + 1).join("/")}/auth/csrf-token`;
      } else {
        parsedUrl.pathname = "/api/auth/csrf-token";
      }
      parsedUrl.search = "";
      parsedUrl.hash = "";
      return parsedUrl.toString();
    }

    async function fetchCsrfTokenForRequest(url) {
      if (csrfRuntime.token) {
        return csrfRuntime.token;
      }
      if (csrfRuntime.promise) {
        return csrfRuntime.promise;
      }
      csrfRuntime.promise = fetch(getCsrfTokenUrl(url), {
        method: "GET",
        credentials: "include",
        cache: "no-store",
        headers: {
          Accept: "application/json"
        }
      })
        .then(async (response) => {
          const payload = await response.json().catch(() => null);
          if (!response.ok || !payload?.csrfToken) {
            const error = new Error(payload?.error || "CSRF token haikupatikana.");
            error.status = response.status;
            error.code = "csrf_unavailable";
            throw error;
          }
          csrfRuntime.token = String(payload.csrfToken || "");
          return csrfRuntime.token;
        })
        .finally(() => {
          csrfRuntime.promise = null;
        });
      return csrfRuntime.promise;
    }

    async function applyCsrfHeader(url, requestOptions) {
      const method = String(requestOptions.method || "GET").toUpperCase();
      if (!isUnsafeApiMethod(method)) {
        return requestOptions;
      }
      const headers = new Headers(requestOptions.headers || {});
      if (!headers.has("X-CSRF-Token")) {
        headers.set("X-CSRF-Token", await fetchCsrfTokenForRequest(url));
      }
      requestOptions.headers = headers;
      return requestOptions;
    }

    function clearCsrfToken() {
      csrfRuntime.token = "";
    }

    function dispatchSessionInvalidated(status, message) {
      const targetWindow = getWindow();
      safeStorageRemove(sessionKey);
      if (typeof targetWindow !== "undefined" && typeof targetWindow.dispatchEvent === "function" && typeof targetWindow.CustomEvent === "function") {
        targetWindow.dispatchEvent(new targetWindow.CustomEvent("winga:session-invalidated", {
          detail: { status, message }
        }));
      }
    }

    async function fetchJson(url, options) {
      const targetWindow = getWindow();
      const startedAt = Date.now();
      const endpointLabel = getApiEndpointLabel(url);
      const requestOptions = options ? { ...options } : {};
      const hasRetriedCsrf = requestOptions.csrfRetry === true;
      delete requestOptions.csrfRetry;
      const externalSignal = requestOptions.signal;
      delete requestOptions.signal;
      const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
      const detachAbortSignal = bindAbortSignal(controller, externalSignal);
      const timeoutMs = Number(
        requestOptions.timeoutMs
        || targetWindow.WINGA_CONFIG?.requestTimeoutMs
        || 25000
      );
      delete requestOptions.timeoutMs;
      const timeoutId = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
      let response;
      try {
        await applyCsrfHeader(url, requestOptions);
        response = await fetch(url, {
          ...requestOptions,
          credentials: requestOptions.credentials || "include",
          signal: controller ? controller.signal : externalSignal
        });
      } catch (error) {
        detachAbortSignal();
        if (timeoutId) {
          clearTimeout(timeoutId);
        }
        const latencyMs = Date.now() - startedAt;
        if (error?.name === "AbortError") {
          const wasExternallyAborted = Boolean(externalSignal?.aborted);
          const endpoint = String(url || "");
          let message = "Request took too long. Check your connection and try again.";
          let code = "timeout";
          if (wasExternallyAborted) {
            message = "Request was cancelled because a newer auth action started.";
            code = "aborted";
          } else {
            if (endpoint.includes("/auth/signup")) {
              message = "Seller signup took too long. Check your connection and try again.";
            }
            if (endpoint.includes("/auth/admin-login")) {
              message = "Admin login took too long. Check your connection and try again.";
            }
            if (endpoint.includes("/auth/login")) {
              message = "Login took too long. Check your connection and try again.";
            }
          }
          emitApiMetric({ endpoint: endpointLabel, ok: false, status: 0, code, latencyMs });
          throw createRequestError(message, {
            code,
            retryable: !wasExternallyAborted,
            endpoint: endpointLabel,
            latencyMs
          });
        }
        const networkError = createRequestError(error?.message || "Network issue. Check your connection and try again.", {
          code: "network",
          retryable: true,
          endpoint: endpointLabel,
          latencyMs
        });
        emitApiMetric({ endpoint: endpointLabel, ok: false, status: 0, code: "network", latencyMs });
        throw networkError;
      }
      detachAbortSignal();
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
      if (!response.ok) {
        let errorMessage = `Request failed: ${response.status}`;
        let errorCode = "";
        try {
          const errorBody = await response.json();
          if (errorBody?.error) {
            errorMessage = errorBody.error;
          }
          if (errorBody?.code) {
            errorCode = String(errorBody.code || "");
          }
        } catch (_error) {
          // Ignore JSON parse failures and keep fallback message.
        }
        if (response.status === 403 && errorCode === "csrf_failed" && !hasRetriedCsrf) {
          clearCsrfToken();
          return fetchJson(url, {
            ...(options || {}),
            csrfRetry: true
          });
        }
        const normalizedMessage = String(errorMessage || "").toLowerCase();
        const shouldInvalidateSession = response.status === 401
          ? normalizedMessage.includes("session")
            || normalizedMessage.includes("imeisha")
            || normalizedMessage.includes("hakupatikana")
          : response.status === 403
            && (
              normalizedMessage.includes("imesimamishwa")
              || normalizedMessage.includes("imezuiwa")
              || normalizedMessage.includes("imezimwa")
            );
        if (shouldInvalidateSession) {
          dispatchSessionInvalidated(response.status, errorMessage);
        }
        const latencyMs = Date.now() - startedAt;
        emitApiMetric({
          endpoint: endpointLabel,
          ok: false,
          status: response.status,
          code: errorCode || `http_${response.status}`,
          latencyMs
        });
        throw createRequestError(errorMessage, {
          code: errorCode || `http_${response.status}`,
          status: response.status,
          retryable: response.status === 408 || response.status === 429 || response.status >= 500,
          endpoint: endpointLabel,
          latencyMs
        });
      }
      const data = response.status === 204 ? null : await response.json();
      emitApiMetric({
        endpoint: endpointLabel,
        ok: true,
        status: response.status,
        latencyMs: Date.now() - startedAt
      });
      return data;
    }

    return {
      bindAbortSignal,
      emitApiMetric,
      getApiEndpointLabel,
      isUnsafeApiMethod,
      getCsrfTokenUrl,
      fetchCsrfTokenForRequest,
      applyCsrfHeader,
      clearCsrfToken,
      fetchJson
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.createApiRuntime = createApiRuntime;
})();


// src/api/products.js
(() => {
  function createProductApiTools(deps = {}) {
    const getWindow = typeof deps.getWindow === "function" ? deps.getWindow : () => window;
    const defaultPageLimit = Math.max(1, Math.floor(Number(deps.defaultPageLimit || 12) || 12));
    const cursorSeparator = String(deps.cursorSeparator || "|");

    function getProductCreatedTime(product) {
      return new Date(
        product?.createdAt
        || product?.created_at
        || product?.timestamp
        || product?.updatedAt
        || 0
      ).getTime();
    }

    function compareProductsNewestFirst(first, second) {
      const secondTime = getProductCreatedTime(second);
      const firstTime = getProductCreatedTime(first);
      if (secondTime !== firstTime) {
        return secondTime - firstTime;
      }
      return String(second?.id || "").localeCompare(String(first?.id || ""));
    }

    function sortProductsNewestFirst(products = []) {
      return (Array.isArray(products) ? products : []).slice().sort(compareProductsNewestFirst);
    }

    function getConfiguredFeedPageLimit(config = getWindow().WINGA_CONFIG || {}) {
      const explicitLimit = Number(config.feedPageLimit || config.startupProductsPageLimit || config.feedBootstrapLimit);
      if (Number.isFinite(explicitLimit) && explicitLimit > 0) {
        return Math.max(1, Math.floor(explicitLimit));
      }
      const targetWindow = getWindow();
      const viewportWidth = Number(targetWindow.innerWidth || 0);
      const mobileLimit = Number(config.feedPageLimitMobile || defaultPageLimit) || defaultPageLimit;
      const desktopLimit = Number(config.feedPageLimitDesktop || 24) || 24;
      return viewportWidth >= 1024
        ? Math.max(1, Math.floor(desktopLimit))
        : Math.max(1, Math.floor(mobileLimit));
    }

    function buildProductCursor(product) {
      if (!product || typeof product !== "object") {
        return "";
      }
      const timestamp = getProductCreatedTime(product);
      const productId = String(product.id || product.productId || product.slug || "").trim();
      if (!Number.isFinite(timestamp) || timestamp <= 0 || !productId) {
        return "";
      }
      return `${timestamp}${cursorSeparator}${productId}`;
    }

    function parseProductCursor(cursor) {
      const rawCursor = String(cursor || "").trim();
      if (!rawCursor || !rawCursor.includes(cursorSeparator)) {
        return null;
      }
      const [timestampValue, ...idParts] = rawCursor.split(cursorSeparator);
      const timestamp = Number(timestampValue);
      const productId = idParts.join(cursorSeparator).trim();
      if (!Number.isFinite(timestamp) || timestamp <= 0 || !productId) {
        return null;
      }
      return {
        timestamp,
        productId
      };
    }

    function normalizeProductPageWindow(options = {}) {
      const requestedLimit = Number(options.limit || defaultPageLimit);
      const limit = Number.isFinite(requestedLimit) && requestedLimit > 0
        ? Math.max(1, Math.floor(requestedLimit))
        : defaultPageLimit;
      const requestedPage = Number(options.page || 1);
      const cursorValue = String(options.cursor || "").trim();
      const page = Number.isFinite(requestedPage) && requestedPage > 0
        ? Math.max(1, Math.floor(requestedPage))
        : 1;
      return {
        limit,
        page,
        cursor: cursorValue
      };
    }

    function normalizeProductPageResponse(payload, options = {}, mapProduct = (product) => product) {
      const pageWindow = normalizeProductPageWindow(options);
      const isObjectPayload = payload && typeof payload === "object" && !Array.isArray(payload);
      const sourceItems = Array.isArray(payload)
        ? payload
        : (Array.isArray(payload?.items)
          ? payload.items
          : Array.isArray(payload?.products)
            ? payload.products
            : Array.isArray(payload?.data)
              ? payload.data
              : []);
      const normalizedItems = sortProductsNewestFirst(sourceItems.map(mapProduct).filter((item) => item && typeof item === "object"));
      const cursorTarget = pageWindow.cursor ? parseProductCursor(pageWindow.cursor) : null;
      const cursorIndex = cursorTarget
        ? normalizedItems.findIndex((item) => {
          const itemCursor = buildProductCursor(item);
          return itemCursor && itemCursor === pageWindow.cursor;
        })
        : -1;
      const pageIndex = Math.max(0, (pageWindow.page - 1) * pageWindow.limit);
      const startIndex = cursorIndex >= 0
        ? cursorIndex + 1
        : pageIndex;
      const slicedItems = normalizedItems.slice(startIndex, startIndex + pageWindow.limit);
      const inferredNextCursor = slicedItems.length
        ? buildProductCursor(slicedItems[slicedItems.length - 1])
        : "";

      if (isObjectPayload) {
        const hasExplicitTotal = Number.isFinite(Number(payload.total));
        const total = hasExplicitTotal
          ? Math.max(0, Math.floor(Number(payload.total)))
          : normalizedItems.length;
        const limit = Number.isFinite(Number(payload.limit)) && Number(payload.limit) > 0
          ? Math.max(1, Math.floor(Number(payload.limit)))
          : pageWindow.limit;
        const page = Number.isFinite(Number(payload.page)) && Number(payload.page) > 0
          ? Math.max(1, Math.floor(Number(payload.page)))
          : pageWindow.page;
        const items = normalizedItems;
        const hasMore = typeof payload.hasMore === "boolean"
          ? payload.hasMore
          : Boolean(payload.nextCursor || payload.cursor)
            || (hasExplicitTotal ? (page * limit) < total : items.length >= limit);
        const nextCursor = payload.nextCursor != null
          ? String(payload.nextCursor)
          : payload.cursor != null
            ? String(payload.cursor)
            : (hasMore ? (items.length ? buildProductCursor(items[items.length - 1]) : "") : "");
        return {
          items,
          nextCursor,
          hasMore,
          total,
          page,
          limit
        };
      }

      const total = normalizedItems.length;
      const items = slicedItems;
      const hasMore = startIndex + items.length < total;
      return {
        items,
        nextCursor: hasMore ? inferredNextCursor : "",
        hasMore,
        total,
        page: pageWindow.page,
        limit: pageWindow.limit
      };
    }

    function mergeUniqueProducts(existingProducts = [], incomingProducts = []) {
      const merged = [];
      const seenIds = new Set();
      const addProduct = (product) => {
        if (!product || typeof product !== "object") {
          return;
        }
        const productId = String(product.id || product.productId || product.slug || "").trim();
        if (productId && seenIds.has(productId)) {
          return;
        }
        if (productId) {
          seenIds.add(productId);
        }
        merged.push(product);
      };

      (Array.isArray(existingProducts) ? existingProducts : []).forEach(addProduct);
      (Array.isArray(incomingProducts) ? incomingProducts : []).forEach(addProduct);
      return merged;
    }

    function filterProductsForQuery(products = [], options = {}) {
      const query = String(options.query || "").trim().toLowerCase();
      const category = String(options.category || "").trim().toLowerCase();
      const seller = String(options.seller || "").trim().toLowerCase();
      return (Array.isArray(products) ? products : []).filter((product) => {
        const productCategory = String(product?.category || "").trim().toLowerCase();
        if (seller && String(product?.uploadedBy || "").trim().toLowerCase() !== seller) {
          return false;
        }
        if (
          category
          && category !== "all"
          && productCategory !== category
          && !productCategory.startsWith(`${category}-`)
        ) {
          return false;
        }
        if (!query) {
          return true;
        }
        return [
          product?.name,
          product?.shop,
          product?.uploadedBy,
          product?.category
        ].map((value) => String(value || "").toLowerCase()).join(" ").includes(query);
      });
    }

    return {
      getProductCreatedTime,
      compareProductsNewestFirst,
      sortProductsNewestFirst,
      getConfiguredFeedPageLimit,
      buildProductCursor,
      parseProductCursor,
      normalizeProductPageWindow,
      normalizeProductPageResponse,
      mergeUniqueProducts,
      filterProductsForQuery
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.products = window.WingaModules.api.products || {};
  window.WingaModules.api.products.createProductApiTools = createProductApiTools;
})();


// src/api/feed-state.js
(() => {
  function createProductFeedStateTools(deps = {}) {
    const state = deps.state && typeof deps.state === "object" ? deps.state : {};
    const defaultPageLimit = Math.max(1, Math.floor(Number(deps.defaultPageLimit || 12) || 12));
    const sortProductsNewestFirst = typeof deps.sortProductsNewestFirst === "function"
      ? deps.sortProductsNewestFirst
      : (products = []) => (Array.isArray(products) ? products : []).slice();
    const mergeUniqueProducts = typeof deps.mergeUniqueProducts === "function"
      ? deps.mergeUniqueProducts
      : (existingProducts = [], incomingProducts = []) => [
        ...(Array.isArray(existingProducts) ? existingProducts : []),
        ...(Array.isArray(incomingProducts) ? incomingProducts : [])
      ];

    function setFullProductFeedPagination(productsList = []) {
      const total = Array.isArray(productsList) ? productsList.length : 0;
      state.productFeedPagination = {
        limit: Math.max(defaultPageLimit, total || defaultPageLimit),
        page: 1,
        nextCursor: "",
        hasMore: false,
        total,
        loadedCount: total
      };
    }

    function setPagedProductFeedPagination(pageInfo = {}, loadedCount = 0) {
      state.productFeedPagination = {
        limit: Number(pageInfo.limit || defaultPageLimit) || defaultPageLimit,
        page: Number(pageInfo.page || 1) || 1,
        nextCursor: String(pageInfo.nextCursor || ""),
        hasMore: Boolean(pageInfo.hasMore),
        total: Number(pageInfo.total || loadedCount || 0),
        loadedCount: Number(loadedCount || 0)
      };
    }

    function applyLoadedProductPageToState(loadedProducts, options = {}) {
      const {
        replace = false,
        markHydrated = false,
        requestState = ""
      } = options;
      const nextProducts = Array.isArray(loadedProducts)
        ? loadedProducts
        : Array.isArray(loadedProducts?.items)
          ? loadedProducts.items
          : Array.isArray(loadedProducts?.products)
            ? loadedProducts.products
            : Array.isArray(loadedProducts?.data)
              ? loadedProducts.data
              : [];

      const safeProducts = sortProductsNewestFirst(
        nextProducts.filter((product) => product && typeof product === "object")
      );
      const existingProducts = Array.isArray(state.products) ? state.products : [];

      if (replace || existingProducts.length === 0) {
        state.products = safeProducts.slice();
      } else if (safeProducts.length > 0) {
        state.products = sortProductsNewestFirst(mergeUniqueProducts(existingProducts, safeProducts));
      }

      if (Array.isArray(loadedProducts)) {
        state.productFeedPagination = {
          limit: safeProducts.length || defaultPageLimit,
          page: 1,
          nextCursor: "",
          hasMore: false,
          total: state.products.length || safeProducts.length,
          loadedCount: state.products.length || safeProducts.length
        };
      } else if (loadedProducts && typeof loadedProducts === "object") {
        state.productFeedPagination = {
          limit: Number(loadedProducts.limit || defaultPageLimit) || defaultPageLimit,
          page: Number(loadedProducts.page || 1) || 1,
          nextCursor: String(loadedProducts.nextCursor || ""),
          hasMore: Boolean(loadedProducts.hasMore),
          total: Number(loadedProducts.total || state.products.length || safeProducts.length || 0),
          loadedCount: state.products.length || safeProducts.length
        };
      } else {
        setFullProductFeedPagination(state.products);
      }

      if (markHydrated) {
        state.productsHydrated = true;
      }
      if (requestState) {
        state.initialProductsRequestState = requestState;
      }

      return safeProducts;
    }

    function getNextProductsPageOptions() {
      const pagination = state.productFeedPagination || {};
      const limit = Number(pagination.limit || defaultPageLimit) || defaultPageLimit;
      const cursor = String(pagination.nextCursor || "").trim();
      const page = Number.isFinite(Number(pagination.page)) && Number(pagination.page) > 0
        ? Math.max(1, Math.floor(Number(pagination.page))) + 1
        : 2;
      return {
        limit,
        page: Number.isFinite(page) && page > 0 ? page : 2,
        cursor
      };
    }

    return {
      setFullProductFeedPagination,
      setPagedProductFeedPagination,
      applyLoadedProductPageToState,
      getNextProductsPageOptions
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.feedState = window.WingaModules.api.feedState || {};
  window.WingaModules.api.feedState.createProductFeedStateTools = createProductFeedStateTools;
})();


// src/api/auth-client.js
(() => {
  function createAuthApiClient(deps = {}) {
    const baseUrl = String(deps.baseUrl || "").replace(/\/+$/, "");
    const sessionAdapter = deps.sessionAdapter || {};
    const fetchJson = typeof deps.fetchJson === "function" ? deps.fetchJson : null;
    const authFetchJson = typeof deps.authFetchJson === "function" ? deps.authFetchJson : fetchJson;
    const createAuthHeaders = typeof deps.createAuthHeaders === "function" ? deps.createAuthHeaders : () => ({});
    const emitApiMetric = typeof deps.emitApiMetric === "function" ? deps.emitApiMetric : () => {};
    const stripSignupCategoryFields = typeof deps.stripSignupCategoryFields === "function"
      ? deps.stripSignupCategoryFields
      : (payload) => payload;
    const normalizePrimaryCategoryValue = typeof deps.normalizePrimaryCategoryValue === "function"
      ? deps.normalizePrimaryCategoryValue
      : (value) => String(value || "").trim();
    const getWindow = typeof deps.getWindow === "function" ? deps.getWindow : () => window;
    let sessionRestoreController = null;

    function requireFetcher() {
      if (typeof fetchJson !== "function" || typeof authFetchJson !== "function") {
        throw new Error("Winga auth API client requires fetch helpers.");
      }
    }

    function jsonHeaders() {
      return {
        "Content-Type": "application/json",
        ...createAuthHeaders()
      };
    }

    function cancelSessionRestore(reason = "auth_interaction") {
      if (!sessionRestoreController) {
        return;
      }
      try {
        sessionRestoreController.abort();
      } catch (_error) {
        // Ignore duplicate abort attempts.
      }
      sessionRestoreController = null;
      emitApiMetric({
        endpoint: "/auth/session",
        ok: false,
        status: 0,
        code: "aborted",
        latencyMs: 0,
        reason
      });
    }

    async function logoutSession() {
      requireFetcher();
      try {
        return await fetchJson(`${baseUrl}/auth/logout`, {
          method: "POST"
        });
      } finally {
        sessionAdapter.clearSession?.();
      }
    }

    async function restoreSession() {
      requireFetcher();
      cancelSessionRestore("restart_session_restore");
      sessionRestoreController = typeof AbortController !== "undefined" ? new AbortController() : null;
      const requestSignal = sessionRestoreController ? sessionRestoreController.signal : undefined;
      try {
        const targetWindow = getWindow();
        const data = await fetchJson(`${baseUrl}/auth/session`, {
          headers: {
            ...createAuthHeaders()
          },
          signal: requestSignal,
          timeoutMs: Number(targetWindow.WINGA_CONFIG?.sessionRestoreTimeoutMs || 5000)
        });
        if (!data || typeof data !== "object" || Array.isArray(data) || !String(data.username || "").trim()) {
          sessionAdapter.clearSession?.();
          return null;
        }
        sessionAdapter.saveSession?.(data);
        return data;
      } catch (error) {
        if (error?.code === "aborted") {
          return null;
        }
        sessionAdapter.clearSession?.();
        return null;
      } finally {
        if (!sessionRestoreController || sessionRestoreController.signal === requestSignal) {
          sessionRestoreController = null;
        }
      }
    }

    async function signup(payload) {
      requireFetcher();
      return authFetchJson(`${baseUrl}/auth/signup`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(stripSignupCategoryFields(payload))
      }, {
        retries: 0
      });
    }

    async function login(payload) {
      requireFetcher();
      return authFetchJson(`${baseUrl}/auth/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      }, {
        retries: 1
      });
    }

    async function requestPasswordRecovery(payload) {
      requireFetcher();
      return authFetchJson(`${baseUrl}/auth/recovery/request`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      }, {
        retries: 0
      });
    }

    async function completePasswordRecovery(payload) {
      requireFetcher();
      return authFetchJson(`${baseUrl}/auth/recovery/complete`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      }, {
        retries: 0
      });
    }

    async function adminLogin(payload) {
      requireFetcher();
      return authFetchJson(`${baseUrl}/auth/admin-login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      }, {
        retries: 1
      });
    }

    async function updateUserProfile(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/users/me/profile`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function upgradeBuyerToSeller(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/users/me/upgrade-to-seller`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function requestWhatsappChange(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/users/me/whatsapp/request-change`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function verifyWhatsappChange(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/users/me/whatsapp/verify-change`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function loadActiveSessions() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/auth/sessions`, {
        headers: createAuthHeaders()
      });
      return {
        items: Array.isArray(data?.items) ? data.items : [],
        count: Number(data?.count || 0),
        maxActivePerUser: Number(data?.maxActivePerUser || 0),
        rotationIntervalSeconds: Number(data?.rotationIntervalSeconds || 0),
        policy: data?.policy && typeof data.policy === "object" ? data.policy : null,
        auditTrail: Array.isArray(data?.auditTrail) ? data.auditTrail : []
      };
    }

    async function revokeActiveSession(sessionId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/auth/sessions/${encodeURIComponent(String(sessionId || ""))}`, {
        method: "DELETE",
        headers: createAuthHeaders()
      });
    }

    async function verifySessionStepUp(password) {
      requireFetcher();
      return fetchJson(`${baseUrl}/auth/step-up`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify({ password })
      });
    }

    async function loadLocalePreference() {
      requireFetcher();
      return fetchJson(`${baseUrl}/users/me/locale-preference`, {
        headers: createAuthHeaders(),
        cache: "no-store"
      });
    }

    async function saveLocalePreference(preference = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/users/me/locale-preference`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(preference)
      });
    }

    async function updateUserPrimaryCategory(username, primaryCategory) {
      requireFetcher();
      const normalizedCategory = normalizePrimaryCategoryValue(primaryCategory);
      if (!normalizedCategory) {
        return { ok: true, ignored: true };
      }
      await fetchJson(`${baseUrl}/users/primary-category`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify({ username, primaryCategory: normalizedCategory })
      });
      return { ok: true };
    }

    return {
      cancelSessionRestore,
      logoutSession,
      restoreSession,
      signup,
      login,
      requestPasswordRecovery,
      completePasswordRecovery,
      adminLogin,
      updateUserProfile,
      upgradeBuyerToSeller,
      requestWhatsappChange,
      verifyWhatsappChange,
      loadActiveSessions,
      revokeActiveSession,
      verifySessionStepUp,
      loadLocalePreference,
      saveLocalePreference,
      updateUserPrimaryCategory
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.auth = window.WingaModules.api.auth || {};
  window.WingaModules.api.auth.createAuthApiClient = createAuthApiClient;
})();


// src/api/products-client.js
(() => {
  function createProductsApiClient(deps = {}) {
    const baseUrl = String(deps.baseUrl || "").replace(/\/+$/, "");
    const fetchJson = typeof deps.fetchJson === "function" ? deps.fetchJson : null;
    const createAuthHeaders = typeof deps.createAuthHeaders === "function" ? deps.createAuthHeaders : () => ({});
    const resolveProductImages = typeof deps.resolveProductImages === "function" ? deps.resolveProductImages : (product) => product;
    const getAnonymousDemandSessionId = typeof deps.getAnonymousDemandSessionId === "function"
      ? deps.getAnonymousDemandSessionId
      : () => "";
    const productUploadTimeoutMs = Number(deps.productUploadTimeoutMs || 180000);

    function requireFetcher() {
      if (typeof fetchJson !== "function") {
        throw new Error("Winga products API client requires fetchJson.");
      }
    }

    function jsonHeaders() {
      return {
        "Content-Type": "application/json",
        ...createAuthHeaders()
      };
    }

    function authHeaders() {
      return {
        ...createAuthHeaders()
      };
    }

    async function requestVideoUpload(file = {}) {
      requireFetcher();
      const idempotencyKey = String(file.idempotencyKey || "").trim();
      return fetchJson(`${baseUrl}/media/videos/direct-upload`, {
        method: "POST",
        headers: {
          ...jsonHeaders(),
          ...(idempotencyKey ? { "Idempotency-Key": idempotencyKey } : {})
        },
        body: JSON.stringify({
          fileName: String(file.name || "").trim(),
          contentType: String(file.type || "").trim().toLowerCase(),
          fileSize: Number(file.size || 0),
          durationSeconds: Math.max(0, Number(file.durationSeconds || 0) || 0),
          uploadProtocol: "tus",
          ...(idempotencyKey ? { idempotencyKey } : {})
        }),
        timeoutMs: productUploadTimeoutMs
      });
    }
    async function readVideoUploadStatus(providerId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/media/videos/${encodeURIComponent(String(providerId || "").trim())}`, {
        headers: authHeaders(),
        timeoutMs: productUploadTimeoutMs
      });
    }
    async function requestVideoPlayback(providerId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/media/videos/${encodeURIComponent(String(providerId || "").trim())}/playback-token`, {
        method: "POST",
        headers: jsonHeaders(),
        body: "{}",
        timeoutMs: 15000
      });
    }
    async function readVideoCaptions(providerId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/media/videos/${encodeURIComponent(String(providerId || "").trim())}/captions`, {
        headers: authHeaders(),
        timeoutMs: 15000
      });
    }
    async function createProduct(product) {
      requireFetcher();
      const result = await fetchJson(`${baseUrl}/products`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(product),
        timeoutMs: productUploadTimeoutMs
      });
      return resolveProductImages(result);
    }

    async function updateProduct(productId, payload) {
      requireFetcher();
      const result = await fetchJson(`${baseUrl}/products/${encodeURIComponent(productId)}`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload),
        timeoutMs: productUploadTimeoutMs
      });
      return resolveProductImages(result);
    }

    async function deleteProduct(productId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/products/${encodeURIComponent(productId)}`, {
        method: "DELETE",
        headers: authHeaders()
      });
    }

    async function updateProductAvailability(productId, payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/products/${encodeURIComponent(productId)}/availability`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function recordDemand(productId, payload = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/products/${encodeURIComponent(productId)}/demand`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify({
          ...payload,
          sessionId: payload.sessionId || getAnonymousDemandSessionId()
        })
      });
    }

    async function moderateProduct(productId, payload) {
      requireFetcher();
      const result = await fetchJson(`${baseUrl}/admin/products/${encodeURIComponent(productId)}/moderate`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
      return resolveProductImages(result);
    }

    async function likeProduct(productId, liked = true) {
      requireFetcher();
      const result = await fetchJson(`${baseUrl}/products/${encodeURIComponent(productId)}/like?liked=${liked ? "true" : "false"}`, {
        method: "POST",
        headers: authHeaders()
      });
      return resolveProductImages(result);
    }

    async function trackProductView(productId) {
      requireFetcher();
      const result = await fetchJson(`${baseUrl}/products/${encodeURIComponent(productId)}/view`, {
        method: "POST",
        headers: {
          ...authHeaders(),
          "X-Winga-Audience-Id": getAnonymousDemandSessionId()
        }
      });
      return resolveProductImages(result);
    }

    return {
      requestVideoUpload,
      readVideoUploadStatus,
      requestVideoPlayback,
      readVideoCaptions,
      createProduct,
      updateProduct,
      deleteProduct,
      updateProductAvailability,
      recordDemand,
      moderateProduct,
      likeProduct,
      trackProductView
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.productActions = window.WingaModules.api.productActions || {};
  window.WingaModules.api.productActions.createProductsApiClient = createProductsApiClient;
})();


// src/api/communications-client.js
(() => {
  function createCommunicationsApiClient(deps = {}) {
    const baseUrl = String(deps.baseUrl || "").replace(/\/+$/, "");
    const fetchJson = typeof deps.fetchJson === "function" ? deps.fetchJson : null;
    const createAuthHeaders = typeof deps.createAuthHeaders === "function" ? deps.createAuthHeaders : () => ({});
    const getEventSource = typeof deps.getEventSource === "function" ? deps.getEventSource : () => globalThis.EventSource;
    let messageCapabilities = null;
    let phoenix = null;
    let encryptedConversations = deps.encryptedConversations || null;
    let candidateReady = null;
    let encryptionReady = null;
    let encryptionOwner = '';
    let encryptionService = null;
    let encryptionChanged = () => {};
    let api;
    const networkFailure = error => error instanceof TypeError || error.status === 503;
    function ensureEncryption() {
      const s = deps.getSession?.();
      if (!s?.username || !globalThis.WingaEncryptionSession) return Promise.resolve(null);
      const key = JSON.stringify([s.username,s.sessionId,s.token]);
      if (key !== encryptionOwner) {
        if(encryptedConversations === encryptionService)encryptedConversations=null;
        encryptionService?.close(); encryptionService = null; encryptionReady = null; encryptionOwner = key;
      }
      if (!encryptionReady) encryptionReady = (async () => {
        let capabilities;
        try { capabilities = await fetchJson(`${baseUrl}/conversations/encrypted/capabilities`, {headers:authHeaders()}); }
        catch(error) { if(error.status === 404) return null; throw error; }
        if(capabilities?.enabled !== true || capabilities.version !== 1) return null;
        const service = await globalThis.WingaEncryptionSession.createEncryptionSession({
          getSession:deps.getSession,deviceRequest:api.cryptoDeviceRequest,
          initialSync:false,
          packageRequest:(payload,context)=>api.cryptoPackageRequest('POST',payload,context),
          operationRequest:payload=>fetchJson(`${baseUrl}/conversations/encrypted/operations`,{method:'POST',headers:jsonHeaders(),body:JSON.stringify(payload)}),
          onChange:()=>encryptionChanged(),
          mediaEnabled:capabilities.mediaEnabled===true,multiDeviceEnabled:capabilities.multiDeviceEnabled===true,mediaRequest:api.cryptoMediaRequest,
          roomsEnabled:capabilities.roomsEnabled===true,
          roomLimits:capabilities.roomLimits,
        });
        if(encryptionOwner !== key) {service.close();throw new Error('mls_session_changed');}
        encryptedConversations = encryptionService = service;return service;
      })().catch(error=>{if(encryptionOwner===key)encryptionReady=null;throw error;});
      return encryptionReady;
    }
    async function isEncryptedConversation(peer) {
      await ensureEncryption();
      const active = deps.getSession?.(), session = active ? { ...active } : null;
      const validName = value => typeof value === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(value);
      const unchanged = () => {
        const current = deps.getSession?.();
        if (session && (current?.username !== session.username || current?.sessionId !== session.sessionId || current?.token !== session.token)) {
          throw Object.assign(new Error('mls_session_changed'), { code: 'mls_session_changed' });
        }
      };
      const stored = validName(session?.username) && validName(peer) && peer !== session.username && globalThis.WingaEncryptedPolicy
        ? await globalThis.WingaEncryptedPolicy.isEncrypted(session.username, peer) : false;
      unchanged();
      const loaded = encryptedConversations ? await encryptedConversations.isEncrypted(peer) : false;
      unchanged();
      if(stored || loaded)return true;
      if(globalThis.WingaEncryptionSession && validName(session?.username) && validName(peer) && peer!==session.username) {
        const mode=await fetchJson(`${baseUrl}/conversations/encrypted/mode?peer=${encodeURIComponent(peer)}`,{headers:authHeaders()});
        unchanged();if(mode?.version!==1 || !['encrypted','legacy-plaintext'].includes(mode.mode))runtimeRequired();
        if(mode.mode==='encrypted'){await globalThis.WingaEncryptedPolicy.markEncrypted(session.username,peer);unchanged();return true;}
      }
      return false;
    }
    const runtimeRequired = () => { throw Object.assign(new Error('mls_runtime_required'), { code: 'mls_runtime_required' }); };

    async function prepareMessage(payload) {
      requireFetcher();
      if (payload?.clientMessageId) return payload;
      if (await isEncryptedConversation(payload?.receiverId)) {
        if (!encryptedConversations) runtimeRequired();
        const clientMessageId = globalThis.crypto?.randomUUID?.();
        if (!clientMessageId) throw Object.assign(new Error('mls_identifier_unavailable'), { code: 'mls_identifier_unavailable' });
        return { ...payload, clientMessageId };
      }
      if (!messageCapabilities) {
        messageCapabilities = fetchJson(`${baseUrl}/messages/capabilities`, { headers: authHeaders() })
          .catch((error) => {
            messageCapabilities = null;
            if (error.status === 404) return { durableMessageRetries: false };
            throw error;
          });
      }
      const capabilities = await messageCapabilities;
      if (capabilities?.durableMessageRetries !== true) return payload;
      const clientMessageId = globalThis.crypto?.randomUUID?.();
      if (!clientMessageId) throw new Error("Secure message identifiers are unavailable.");
      return { ...payload, clientMessageId };
    }

    function requireFetcher() {
      if (typeof fetchJson !== "function") {
        throw new Error("Winga communications API client requires fetchJson.");
      }
    }

    function jsonHeaders() {
      return {
        "Content-Type": "application/json",
        ...createAuthHeaders()
      };
    }

    function authHeaders() {
      return {
        ...createAuthHeaders()
      };
    }

    async function loadMessages() {
      requireFetcher();
      const encrypted = await ensureEncryption();
      if(encrypted)try{await encrypted.sync();}catch(error){if(!networkFailure(error))throw error;}
      let data;
      try { data=await fetchJson(`${baseUrl}/messages`, {headers:authHeaders()}); }
      catch(error){if(!encrypted || !networkFailure(error))throw error;data=[];}
      return [...(Array.isArray(data) ? data : []), ...(encrypted ? await encrypted.history() : [])];
    }

    async function loadInboxSnapshot(params) {
      const sessionKey = () => JSON.stringify([deps.getSession?.()?.username, deps.getSession?.()?.sessionId, deps.getSession?.()?.token]);
      const ownerKey = sessionKey(), owner = deps.getSession?.()?.username;
      const current = () => {
        if (sessionKey() !== ownerKey) throw Object.assign(new Error('mls_session_changed'), {code:'mls_session_changed'});
      };
      // A failed encrypted refresh must not disable an otherwise healthy inbox.
      const page = await fetchJson(`${baseUrl}/messages/inbox?${params}`, {headers:authHeaders()});
      current();
      if (!page || !Array.isArray(page.items)) throw new Error('INVALID_INBOX_PAGE');
      let encrypted, history = [], encryptedSyncError = false;
      const unavailable = error => {
        current();
        if (error.status === 401 || error.status === 403 || error.code === 'mls_session_changed' || error.message === 'mls_session_changed') throw error;
        encryptedSyncError = true;
      };
      try {encrypted = await ensureEncryption();current();} catch (error) {unavailable(error);}
      if (encrypted) {
        try {await encrypted.sync();current();} catch (error) {unavailable(error);}
        try {
          history = await encrypted.history();current();
          if (!Array.isArray(history)) throw new Error('INVALID_ENCRYPTED_HISTORY');
        } catch (error) {history = [];unavailable(error);}
      }
      const merged = new Map(page.items.map(item => [item.withUser, item]));
      const unread = new Map();
      for (const item of history) {
        if(item.eventRecord)continue;
        if (!owner || ![item.senderId, item.receiverId].includes(owner)) continue;
        const peer = item.senderId === owner ? item.receiverId : item.senderId;
        if (!peer || peer === owner || !Number.isFinite(Date.parse(item.timestamp))) continue;
        if (item.senderId === peer && !item.isRead) unread.set(peer, (unread.get(peer) || 0) + 1);
        const prior = merged.get(peer);
        if (!prior || Date.parse(item.timestamp) >= Date.parse(prior.timestamp)) merged.set(peer, {...prior,
          withUser:peer,latestMessage:item.message,timestamp:item.timestamp,lastMessageId:item.id,
          productId:'',productName:'',unreadCount:prior?.unreadCount || 0,encrypted:true});
      }
      for (const [peer, count] of unread) {
        const row = merged.get(peer);
        if (row) merged.set(peer, {...row, unreadCount:(page.items.find(item => item.withUser === peer)?.unreadCount || 0) + count});
      }
      current();
      return {...page,encryptedSyncError,totalUnread:(Number(page.totalUnread) || 0) + [...unread.values()].reduce((sum,count)=>sum+count,0),
        items:[...merged.values()].sort((a,b)=>b.timestamp.localeCompare(a.timestamp))};
    }

    async function loadMessagePage(path, options = {}) {
      requireFetcher();
      const params = new URLSearchParams();
      if (options.limit !== undefined) params.set("limit", String(options.limit));
      if (options.cursor) params.set("cursor", options.cursor);
      if (options.withUser) params.set("withUser", options.withUser);
      if (options.order === "sequence") params.set("order", "sequence");
      if (path === 'inbox') return loadInboxSnapshot(params);
      const encrypted = ['inbox','history'].includes(path) ? await ensureEncryption() : null;
      if(encrypted)try{await encrypted.sync();}catch(error){if(!networkFailure(error))throw error;}
      let page;
      try { page=await fetchJson(`${baseUrl}/messages/${path}?${params}`, {headers:authHeaders()}); }
      catch(error){if(!encrypted || !networkFailure(error))throw error;page={items:[],hasMore:false,nextCursor:''};}
      if(!encrypted) return page;
      const history = await encrypted.history(options.withUser);
      if(path === 'history') return {...page,items:[...page.items,...history].sort((a,b)=>a.timestamp.localeCompare(b.timestamp))};
      return page;
    }

    async function sendMessage(payload) {
      requireFetcher();
      if (await isEncryptedConversation(payload?.receiverId)) {
        // Resolve durable mode before touching either legacy transport. A lookup
        // or encryption failure is not permission to send plaintext instead.
        if (!encryptedConversations) runtimeRequired();
        return encryptedConversations.sendMessage(payload);
      }
      if (payload?.encrypted || payload?.securityMode === 'encrypted') {
        throw Object.assign(new Error('mls_runtime_required'), { code: 'mls_runtime_required' });
      }
      const transported = await phoenix?.sendMessage(payload);
      if (transported) return transported;
      return fetchJson(`${baseUrl}/messages`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function deleteMessage(messageId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/messages/${encodeURIComponent(messageId)}`, {
        method: "DELETE",
        headers: authHeaders()
      });
    }

    async function markConversationRead(payload) {
      requireFetcher();
      const encrypted=await ensureEncryption();
      if(encrypted && await encrypted.isEncrypted(payload.withUser)) {
        await encrypted.markRead(payload.withUser,payload.messageIds);return {ok:true};
      }
      return fetchJson(`${baseUrl}/messages/read`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function loadChatDevice() {
      requireFetcher();
      return fetchJson(`${baseUrl}/messages/device`, { headers: authHeaders() });
    }

    async function acknowledgeMessages(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/messages/receipts`, {
        method: "POST", headers: jsonHeaders(), body: JSON.stringify(payload)
      });
    }

    async function loadConversationOffers(withUser) {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/conversations/${encodeURIComponent(withUser)}/offers`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function createConversationOffer(withUser, payload, idempotencyKey) {
      requireFetcher();
      return fetchJson(`${baseUrl}/conversations/${encodeURIComponent(withUser)}/offers`, {
        method: "POST",
        headers: {
          ...jsonHeaders(),
          "Idempotency-Key": idempotencyKey
        },
        body: JSON.stringify(payload)
      });
    }

    async function transitionConversationOffer(offerId, payload, idempotencyKey) {
      requireFetcher();
      return fetchJson(`${baseUrl}/conversation-offers/${encodeURIComponent(offerId)}`, {
        method: "PATCH",
        headers: {
          ...jsonHeaders(),
          "Idempotency-Key": idempotencyKey
        },
        body: JSON.stringify(payload)
      });
    }

    async function loadConversationAvailabilityRequests(withUser) {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/conversations/${encodeURIComponent(withUser)}/availability-requests`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function findOfferBetterPrice(offerId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/conversation-offers/${encodeURIComponent(offerId)}/better-price`, {
        method: "POST", headers: jsonHeaders(), body: "{}"
      });
    }

    async function createConversationAvailabilityRequest(withUser, payload, idempotencyKey) {
      requireFetcher();
      return fetchJson(`${baseUrl}/conversations/${encodeURIComponent(withUser)}/availability-requests`, {
        method: "POST",
        headers: {
          ...jsonHeaders(),
          "Idempotency-Key": idempotencyKey
        },
        body: JSON.stringify(payload)
      });
    }

    async function transitionConversationAvailabilityRequest(requestId, payload, idempotencyKey) {
      requireFetcher();
      return fetchJson(`${baseUrl}/conversation-availability/${encodeURIComponent(requestId)}`, {
        method: "PATCH",
        headers: {
          ...jsonHeaders(),
          "Idempotency-Key": idempotencyKey
        },
        body: JSON.stringify(payload)
      });
    }

    async function loadNotifications() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/notifications`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function markNotificationRead(notificationId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/notifications/${encodeURIComponent(notificationId)}/read`, {
        method: "PATCH",
        headers: authHeaders()
      });
    }

    function openRealtimeChannel(handlers = {}) {
      encryptionChanged = () => { if(!handlers.isCurrent || handlers.isCurrent()) Promise.resolve(handlers.onMessageRead?.()).catch(()=>{}); };
      let encryptionPolling = false;
      const encryptionTimer = setInterval(async () => {
        if(encryptionPolling || (handlers.isCurrent && !handlers.isCurrent())) return;
        encryptionPolling=true;
        try { const service=await ensureEncryption();if(service)await service.sync(); }
        catch(error) { handlers.onError?.(); }
        finally { encryptionPolling=false; }
      },3000);
      const EventSourceCtor = getEventSource();
      if (typeof EventSourceCtor === "undefined") {
        clearInterval(encryptionTimer);
        return null;
      }

      const source = new EventSourceCtor(`${baseUrl}/messages/stream`, { withCredentials: true });
      const replay = handlers.replayState;
      let closed = false;
      let recovering = false;
      let recoveryRequested = false;
      let recoveryTimer = null;
      const isCurrent = () => !closed && (!handlers.isCurrent || handlers.isCurrent());
      phoenix?.close();
      phoenix = null;
      let deviceStream = null;
      const session = deps.getSession?.();
      const sessionKey = value => JSON.stringify([value?.username || "", value?.sessionId || value?.token || ""]);
      const ownerKey = sessionKey(session);
      const transport = window.WingaModules?.api?.phoenix;
      const config = () => deps.getTransportConfig?.() || {};
      const transportUrl = transport?.canaryUrl(config(), session);
      const canStream = () => isCurrent() && ownerKey === sessionKey(deps.getSession?.())
        && transport?.canaryUrl(config(), deps.getSession?.()) === transportUrl;
      if (transportUrl && typeof handlers.onDeviceEvents === "function") {
        loadChatDevice().then(device => {
          if (!canStream() || device?.supported !== true || device?.eventDelivery !== true
            || device.username !== session.username || !device.deviceId) return;
          deviceStream = transport.createPhoenixTransport({
            url: transportUrl, owner: session.username, deviceId: device.deviceId,
            isCurrent: canStream,
            fetchTicket: () => fetchJson(`${baseUrl}/messages/transport-ticket`, {
              method: "POST", headers: jsonHeaders(), body: "{}"
            }),
            onEvents: handlers.onDeviceEvents,
            onState: handlers.onTransportState
          });
          phoenix = deviceStream;
        }).catch(() => { /* REST/SSE remains active when canary enrollment is unavailable. */ });
      }
      async function recover() {
        if (!replay || !handlers.reconcile || !isCurrent()) return;
        if (recovering) { recoveryRequested = true; return; }
        clearTimeout(recoveryTimer);
        recoveryTimer = null;
        recoveryRequested = false;
        recovering = true;
        let cursor = replay.cursor || "";
        let hasMore = false;
        let resyncRequired = false;
        try {
          for (let page = 0; page < 5; page += 1) {
            let result;
            try {
              result = await loadMessagePage("replay", { cursor, limit: 50 });
            } catch (error) {
              if (error.status === 400 && cursor) {
                cursor = "";
                result = await loadMessagePage("replay", { limit: 50 });
              } else throw error;
            }
            if (!isCurrent()) return;
            if (!result || result.version !== 1 || typeof result.cursor !== "string"
              || !result.cursor || !Array.isArray(result.events)) throw new Error("Invalid replay response");
            if (result.hasMore && result.cursor === cursor) throw new Error("Replay cursor did not advance");
            cursor = result.cursor;
            hasMore = result.hasMore === true;
            // Initial checkpoint precedes reconciliation; catch up again afterwards
            // so messages committed during that reconciliation are not skipped.
            if (result.resyncRequired) { resyncRequired = true; hasMore = true; break; }
            if (!hasMore) break;
          }
          if (!isCurrent()) return;
          await handlers.reconcile({ resyncRequired });
          if (!isCurrent()) return;
          replay.cursor = cursor;
          if (hasMore) recoveryTimer = setTimeout(recover, 250);
        } catch (_error) {
          // Optional recovery cannot disable human chat or advance a failed batch.
          if (isCurrent()) {
            try { await handlers.reconcile({ resyncRequired: true }); } catch (_fallbackError) { /* Existing refresh telemetry owns this failure. */ }
          }
        } finally {
          recovering = false;
          if (recoveryRequested && isCurrent() && !recoveryTimer) {
            recoveryTimer = setTimeout(recover, 250);
          }
        }
      }
      source.addEventListener("open", recover);
      source.addEventListener("message_state_changed", recover);
      source.addEventListener("replay_required", recover);
      const parseEvent = (event) => {
        try {
          return event?.data ? JSON.parse(event.data) : null;
        } catch (_error) {
          return null;
        }
      };

      source.addEventListener("message", (event) => {
        handlers.onMessage?.(parseEvent(event));
      });
      source.addEventListener("notification", (event) => {
        handlers.onNotification?.(parseEvent(event));
      });
      source.addEventListener("message_read", (event) => {
        handlers.onMessageRead?.(parseEvent(event));
      });
      source.addEventListener("conversation_read", (event) => {
        handlers.onConversationRead?.(parseEvent(event));
      });
      source.addEventListener("users", (event) => {
        handlers.onUsers?.(parseEvent(event));
      });
      source.onerror = () => {
        handlers.onError?.();
      };

      return {
        close() {
          clearInterval(encryptionTimer);
          encryptionChanged=()=>{};
          if(encryptedConversations === encryptionService)encryptedConversations=null;
          encryptionService?.close();encryptionService=null;encryptionReady=null;encryptionOwner='';
          closed = true;
          deviceStream?.close();
          if (phoenix === deviceStream) phoenix = null;
          clearTimeout(recoveryTimer);
          source.close();
        }
      };
    }

    return api = {
      shoppingRoom:async(action,args=[])=>{const service=await ensureEncryption();if(!service)runtimeRequired();return service.shoppingRoom(action,args);},
      seller:async(action,args=[])=>{const service=await ensureEncryption();if(!service)runtimeRequired();return service.seller(action,args);},
      inspectEncryptedConversation: async peer => {
        const service=await ensureEncryption();return service?service.inspect(peer):{status:'disabled'};
      },
      enableEncryptedConversation: async (peer,deviceId,fingerprint) => {
        const service=await ensureEncryption();if(!service)runtimeRequired();return service.enable(peer,deviceId,fingerprint);
      },
      replaceEncryptedConversationDevice:async(peer,deviceId,fingerprint)=>{
        const service=await ensureEncryption();if(!service)runtimeRequired();return service.replace(peer,deviceId,fingerprint);
      },
      resumeEncryptedConversationReplacement:async peer=>{
        const service=await ensureEncryption();if(!service)runtimeRequired();return service.resumeReplacement(peer);
      },
      admitEncryptedConversationDevice:async(peer,deviceId,fingerprint)=>{
        const service=await ensureEncryption();if(!service)runtimeRequired();return service.admitDevice(peer,deviceId,fingerprint);
      },
      changeEncryptedConversationDevice:async(peer,removedId,replacementId,fingerprint)=>{
        const service=await ensureEncryption();if(!service)runtimeRequired();return service.changeDevice(peer,removedId,replacementId,fingerprint);
      },
      verifyEncryptedConversationAdmission:async(peer,fingerprints)=>{
        const service=await ensureEncryption();if(!service)runtimeRequired();return service.verifyAdmission(peer,fingerprints);
      },
      sendEncryptedMedia:async(peer,file,text,kind)=>{const s=await ensureEncryption();if(!s)runtimeRequired();return s.sendEncryptedMedia(peer,file,text,kind);},
      stageEncryptedMediaDraft:async(peer,file,kind)=>{const s=await ensureEncryption();if(!s)runtimeRequired();return s.stageMediaDraft(peer,file,kind);},
      readEncryptedMediaDraft:async peer=>{const s=await ensureEncryption();if(!s)runtimeRequired();return s.readMediaDraft(peer);},
      discardEncryptedMediaDraft:async peer=>{const s=await ensureEncryption();if(!s)runtimeRequired();return s.discardMediaDraft(peer);},
      sendEncryptedMediaDraft:async(peer,text)=>{const s=await ensureEncryption();if(!s)runtimeRequired();return s.sendMediaDraft(peer,text);},
      sendRichMessage:async(peer,content)=>sendMessage({clientMessageId:crypto.randomUUID(),receiverId:peer,message:'',richContent:content,encrypted:true}),
      mutateEncryptedMessage:async(peer,type,id,value)=>{const s=await ensureEncryption();if(!s)runtimeRequired();return s.mutateMessage(peer,type,id,value);},
      readConversationReference:async(kind,id)=>{
        requireFetcher();return fetchJson(baseUrl+'/conversations/references?kind='+encodeURIComponent(kind)+'&id='+encodeURIComponent(id),{headers:authHeaders()});
      },
      readRichCatalog:async(kind,query='')=>{
        requireFetcher();const q=String(query).trim().slice(0,120);
        let rows;
        if(['order','payment','delivery'].includes(kind)) {
          const value=await fetchJson(baseUrl+'/orders/mine',{headers:authHeaders()});
          rows=[...new Map([...(value.purchases||[]),...(value.sales||[])].map(item=>[item.id,item])).values()];
          if(kind==='payment')rows=rows.filter(item=>item.paymentIntentStatus);
        }else if(kind==='collection') {
          const value=await fetchJson(baseUrl+'/social/users/'+encodeURIComponent(deps.getSession?.()?.username||'')+'/collections?limit=12',{headers:authHeaders()});
          rows=value.items||[];
        }else {
          const params=new URLSearchParams({limit:'12',q});
          const value=await fetchJson(baseUrl+'/products?'+params,{headers:authHeaders()});
          rows=value.items||value.products||[];
          if(kind==='reel'||kind==='short')rows=rows.filter(p=>(p.mediaItems||[]).some(m=>m.type==='video'&&m.status==='ready'&&m.moderationStatus!=='rejected'));
        }
        return rows.filter(item=>!q||String(item.name||item.title||item.productName||item.id).toLocaleLowerCase().includes(q.toLocaleLowerCase())).slice(0,12);
      },
      readConversationProduct:async id=>{
        requireFetcher();const value=await fetchJson(baseUrl+'/products?limit=1&productId='+encodeURIComponent(id),{headers:authHeaders()});
        const p=(value.items||value.products||[]).find(p=>p.id===id&&p.status==='approved');
        if(!p)throw Object.assign(new Error('conversation_reference_unavailable'),{code:'conversation_reference_unavailable'});
        return p;
      },
      readRichContact:async username=>{
        requireFetcher();if(!/^[A-Za-z0-9._:-]{1,40}$/.test(username))throw new Error('contact_lookup_invalid');
        const value=await fetchJson(baseUrl+'/social/users/'+encodeURIComponent(username),{headers:authHeaders()});
        if(value.profile?.username?.toLocaleLowerCase()!==username.toLocaleLowerCase())throw new Error('contact_lookup_invalid');
        return value.profile;
      },
      downloadEncryptedMedia:async id=>{const s=await ensureEncryption();if(!s)runtimeRequired();return s.downloadEncryptedMedia(id);},
      encryptedRecoveryAvailable:async()=>{try {const r=await fetchJson(`${baseUrl}/conversations/recovery/capabilities`,{headers:authHeaders()});return r.version===1&&r.enabled===true;}catch(error){if(error.status===404)return false;throw error;}},
      createEncryptedRecovery:()=>globalThis.WingaRecoveryUi.createRecoverySession({getSession:deps.getSession,request:api.cryptoRecoveryRequest}),
      cryptoDeviceManagementAvailable:async()=>{try{const r=await fetchJson(`${baseUrl}/conversations/crypto/devices`,{headers:authHeaders()});return r.version===1&&Array.isArray(r.devices);}catch(error){if(error.status===404)return false;throw error;}},
      createCryptoDeviceManagement:()=>globalThis.WingaDeviceManagementUi.createManagementSession({getSession:deps.getSession,request:api.cryptoDeviceRequest}),
      cryptoMediaRequest:async(method,object,proof,blob)=>{
        requireFetcher();if(!['GET','PUT'].includes(method))throw new Error('private_media_invalid');
        const encoded=btoa(JSON.stringify(proof)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
        const response=await fetch(`${baseUrl}/conversations/encrypted/media/${object.id}`,{method,headers:{...jsonHeaders(),'Content-Type':'application/octet-stream','X-Winga-Crypto-Proof':encoded},...(method==='PUT'?{body:blob}:{}),signal:AbortSignal.timeout(30000)});
        if(!response.ok){const value=await response.json();throw Object.assign(new Error(value.code),{code:value.code,status:response.status});}
        if(method==='PUT')return response.json();
        if(response.headers.get('content-type')!=='application/octet-stream')throw new Error('private_media_integrity_rejected');
        const reader=response.body.getReader(),chunks=[];let bytes=0;
        try {while(true){const part=await reader.read();if(part.done)break;bytes+=part.value.length;if(bytes>object.bytes)throw new Error('private_media_integrity_rejected');chunks.push(part.value);}}
        finally {await reader.cancel().catch(()=>{});reader.releaseLock();}
        if(bytes!==object.bytes)throw new Error('private_media_integrity_rejected');return new Blob(chunks,{type:'application/octet-stream'});
      },
      createEncryptedCandidate: options => {
        if (candidateReady) return candidateReady;
        candidateReady = (async () => {
          const session = deps.getSession?.();
          const create = globalThis.WingaMlsCandidate?.createMlsRuntime;
          if (!session?.username || typeof create !== 'function'
            || !globalThis.WingaCryptoDevices?.createCryptoDeviceClient
            || !globalThis.WingaEncryptedVault?.createEncryptedVault) {
            throw Object.assign(new Error('mls_runtime_unavailable'), { code: 'mls_runtime_unavailable' });
          }
          let identityClient, vault, runtime;
          try {
            identityClient = await globalThis.WingaCryptoDevices.createCryptoDeviceClient({
              getSession: deps.getSession, request: api.cryptoDeviceRequest,
            });
            vault = await globalThis.WingaEncryptedVault.createEncryptedVault({ owner: session.username, getSession: deps.getSession });
            runtime = await create({ ...options, getSession: deps.getSession, vault, identityClient,
              publishPackage: (payload, context) => api.cryptoPackageRequest('POST', payload, context) });
            await runtime.initialize();
            const close = runtime.close;
            runtime.close = () => { close(); vault.close(); identityClient.close(); };
            return runtime;
          } catch (error) { runtime?.close(); vault?.close(); identityClient?.close(); throw error; }
        })();
        // Failed opt-in stays fail-closed; it cannot quietly restore legacy send.
        encryptedConversations = {
          isEncrypted: async peer => (await candidateReady).isEncrypted(peer),
          sendMessage: async payload => (await candidateReady).sendMessage(payload),
          retryMessage: async id => (await candidateReady).retryMessage(id),
        };
        return candidateReady;
      },
      isEncryptedConversation,
      retryEncryptedMessage: async id => { await ensureEncryption();return encryptedConversations?.retryMessage ? encryptedConversations.retryMessage(id) : null; },
      prepareMessage,
      cryptoDeviceRequest: (method, payload, context) => {
        requireFetcher();
        const active = deps.getSession?.();
        if (!active || active.username !== context?.owner || active.sessionId !== context.deviceId
          || active.token !== context.token) throw new Error("crypto_device_session_changed");
        if (!['GET', 'POST'].includes(method)) throw new Error("crypto_device_method_invalid");
        return fetchJson(`${baseUrl}/conversations/crypto/devices`, {
          method, headers: method === 'POST' ? jsonHeaders() : authHeaders(),
          ...(method === 'POST' ? { body: JSON.stringify(payload) } : {})
        });
      },
      cryptoPackageRequest: (method, payload, context) => {
        requireFetcher();
        const active = deps.getSession?.();
        if (!active || active.username !== context?.owner || active.sessionId !== context.deviceId
          || active.token !== context.token) throw new Error("crypto_device_session_changed");
        if (!['GET', 'POST'].includes(method)) throw new Error("crypto_device_method_invalid");
        return fetchJson(`${baseUrl}/conversations/crypto/key-packages`, {
          method, headers: method === 'POST' ? jsonHeaders() : authHeaders(),
          ...(method === 'POST' ? { body: JSON.stringify(payload) } : {})
        });
      },
      cryptoRecoveryRequest: (method, payload, context, page) => {
        requireFetcher();
        const active = deps.getSession?.();
        if (!active || active.username !== context?.owner || active.sessionId !== context.deviceId
          || active.token !== context.token) throw new Error("crypto_device_session_changed");
        if (!['GET', 'PUT', 'DELETE'].includes(method)) throw new Error("crypto_device_method_invalid");
        const suffix=page ? `/pages${method==='GET'?`?id=${encodeURIComponent(page.id)}&revision=${encodeURIComponent(page.revision)}`:''}`:'';
        return fetchJson(`${baseUrl}/conversations/recovery${suffix}`, {
          method, headers: method === 'GET' ? authHeaders() : jsonHeaders(),
          ...(method === 'GET' ? {} : { body: JSON.stringify(payload) })
        });
      },
      hasDeviceEventStream: () => phoenix?.isReady() === true,
      loadMessages,
      loadInboxPage: (options) => loadMessagePage("inbox", options),
      loadConversationPage: (withUser, options = {}) => loadMessagePage("history", { ...options, withUser }),
      sendMessage,
      deleteMessage,
      markConversationRead,
      loadChatDevice,
      pollDeviceEvents: () => {
        requireFetcher();
        return fetchJson(`${baseUrl}/messages/device-events/poll`, { method: "POST", headers: jsonHeaders(), body: "{}" });
      },
      acknowledgeDeviceEvents: payload => {
        requireFetcher();
        return fetchJson(`${baseUrl}/messages/device-events/ack`, { method: "POST", headers: jsonHeaders(), body: JSON.stringify(payload) });
      },
      pushRequest: (path, payload, method = "GET") => {
        requireFetcher();
        return fetchJson(`${baseUrl}/messages/push/${path}`, {
          method, headers: jsonHeaders(), ...(payload ? { body: JSON.stringify(payload) } : {})
        });
      },
      loadPendingMessageDelivery: () => loadMessagePage("pending-delivery"),
      acknowledgeMessages,
      loadConversationOffers,
      createConversationOffer,
      transitionConversationOffer,
      findOfferBetterPrice,
      loadConversationAvailabilityRequests,
      createConversationAvailabilityRequest,
      transitionConversationAvailabilityRequest,
      loadNotifications,
      markNotificationRead,
      openRealtimeChannel
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.communications = window.WingaModules.api.communications || {};
  window.WingaModules.api.communications.createCommunicationsApiClient = createCommunicationsApiClient;
})();


// src/api/phoenix-transport.js
(() => {
  let library;
  function loadSocket() {
    if (window.Phoenix?.Socket) return Promise.resolve(window.Phoenix.Socket);
    if (!library) library = new Promise((resolve, reject) => {
      const script = document.createElement("script");
      const finish = error => {
        clearTimeout(timer);
        script.onload = script.onerror = null;
        if (error) { script.remove(); reject(error); }
        else resolve(window.Phoenix.Socket);
      };
      const timer = setTimeout(() => finish(new Error("Phoenix client unavailable.")), 10000);
      script.src = "/vendor/phoenix.min.js?v=1.8.15";
      script.onload = () => finish(window.Phoenix?.Socket ? null : new Error("Phoenix client unavailable."));
      script.onerror = () => finish(new Error("Phoenix client unavailable."));
      document.head.appendChild(script);
    }).catch(error => { library = null; throw error; });
    return library;
  }

  function canaryUrl(config, session, location = window.location) {
    if (config?.phoenixTransportEnabled !== true || !session?.username
      || (config.phoenixAllUsers !== true
        && (!Array.isArray(config.phoenixCanaryUsers) || !config.phoenixCanaryUsers.includes(session.username)))) return "";
    try {
      const url = new URL(config.phoenixTransportUrl);
      const local = ["localhost", "127.0.0.1"].includes(location?.hostname)
        && ["localhost", "127.0.0.1"].includes(url.hostname);
      if ((url.protocol !== "wss:" && !(local && url.protocol === "ws:"))
        || url.username || url.password || url.search || url.hash || url.pathname !== "/socket") return "";
      return url.href;
    } catch { return ""; }
  }

  function textPayload(payload) {
    const fields = new Set(["clientMessageId", "receiverId", "message", "messageType", "productId", "productName", "productItems", "replyToMessageId"]);
    if (!payload || Object.keys(payload).some(key => !fields.has(key)) || !payload.clientMessageId
      || (payload.messageType && payload.messageType !== "text") || payload.productId || payload.productName
      || payload.replyToMessageId || (payload.productItems && (!Array.isArray(payload.productItems) || payload.productItems.length))) return null;
    return { clientMessageId: payload.clientMessageId, receiverId: payload.receiverId, message: payload.message };
  }

  function createPhoenixTransport(deps) {
    const later = deps.setTimeout || setTimeout, cancel = deps.clearTimeout || clearTimeout;
    const now = deps.now || Date.now, random = deps.random || Math.random;
    let closed = false, epoch = 0, socket = null, channel = null, timer = null, deadline = null;
    let joined = false, receiving = false, attempts = 0, expiresAt = 0;
    let joinWhenOpen = null;
    const pending = new Set();
    const report = (state, phase) => { try { deps.onState?.({transport: "phoenix", state, phase}); } catch {} };
    const failure = (code = "transport_unavailable", status = 503) => Object.assign(
      new Error("Conversation transport request was not confirmed."), { code, status, retryable: status >= 500 });
    const current = generation => !closed && epoch === generation && deps.isCurrent();
    const isReady = () => current(epoch) && joined && now() < expiresAt && channel?.canPush() === true;
    function reset() {
      epoch++;
      joined = false;
      expiresAt = 0;
      receiving = false;
      cancel(timer); cancel(deadline);
      timer = deadline = null;
      for (const reject of [...pending]) reject(failure("outcome_unknown"));
      pending.clear();
      const old = channel;
      channel = null;
      joinWhenOpen = null;
      socket?.disconnect();
      old?.leave(1);
    }
    function close() { closed = true; reset(); }
    function retry(generation, error) {
      if (!current(generation)) return;
      if ([401, 403, 404].includes(error?.status)) { close(); return; }
      reset();
      const delay = Math.min(30000, 1000 * 2 ** Math.min(attempts++, 5)) * (0.8 + random() * 0.4);
      timer = later(start, delay);
    }
    function command(event, payload, generation = epoch) {
      return new Promise((resolve, reject) => {
        if (!current(generation) || !isReady() || pending.size >= 8) return reject(failure());
        let done = false, timeout;
        const finish = (error, result) => {
          if (done) return;
          done = true; cancel(timeout); pending.delete(abort);
          if (error) reject(error);
          else if (!current(generation)) reject(failure("outcome_unknown"));
          else resolve(result);
        };
        const abort = error => finish(error);
        pending.add(abort);
        timeout = later(() => finish(failure("outcome_unknown")), 8000);
        try {
          channel.push(event, payload, 8000)
            .receive("ok", result => finish(null, result))
            .receive("error", result => finish(failure(result?.code === "rejected" ? "message_rejected" : "outcome_unknown",
              result?.code === "rejected" ? 409 : 503)))
            .receive("timeout", () => finish(failure("outcome_unknown")));
        } catch { finish(failure("outcome_unknown")); }
      });
    }
    async function start() {
      if (closed || !deps.isCurrent()) { close(); return; }
      reset();
      const generation = epoch;
      deadline = later(() => retry(generation), 15000);
      let phase = "library";
      try {
        const Socket = await (deps.loadSocket || loadSocket)();
        if (!current(generation)) return;
        phase = "ticket";
        const ticket = await deps.fetchTicket();
        if (!current(generation)) return;
        if (ticket?.version !== 1 || typeof ticket.ticket !== "string" || ticket.ticket.length > 2048
          || !Number.isSafeInteger(ticket.expiresAt) || ticket.expiresAt <= now() + 1000) throw failure();
        phase = "socket";
        if (!socket) {
          socket = new Socket(deps.url, { params: {}, timeout: 8000, heartbeatIntervalMs: 20000 });
          socket.onOpen(() => {
            if (closed || !deps.isCurrent()) { close(); return; }
            if (joinWhenOpen) joinWhenOpen();
            else start(); // Browser resume requires a fresh scoped ticket.
          });
          socket.onClose(() => { report("unavailable", "socket_closed"); retry(epoch); });
          socket.onError(() => { report("unavailable", "socket_error"); retry(epoch); });
        }
        phase = "channel";
        channel = socket.channel("device", { ticket: ticket.ticket });
        channel.onError(() => { report("unavailable", "channel_error"); retry(generation); });
        channel.onClose(() => { report("unavailable", "channel_closed"); retry(generation); });
        channel.on("events", async batch => {
          if (!current(generation) || !joined) return;
          if (receiving) { retry(generation); return; }
          receiving = true;
          try {
            const persisted = await deps.onEvents(batch, ids => command("events.ack", { eventIds: ids }, generation));
            if (persisted !== true) throw failure();
          } catch (error) { retry(generation, error); }
          finally { if (current(generation)) receiving = false; }
        });
        phase = "join";
        // Join only on an open socket: the SDK must never buffer an old ticket.
        joinWhenOpen = () => {
          if (!current(generation)) return;
          joinWhenOpen = null;
          channel.join(8000).receive("ok", principal => {
            if (!current(generation)) return;
            if (principal?.deviceId !== deps.deviceId || principal?.securityMode !== "legacy-plaintext"
              || principal?.expiresAt !== ticket.expiresAt) { close(); return; }
            cancel(deadline); deadline = null;
            joined = true; attempts = 0; expiresAt = ticket.expiresAt;
            report("ready", "joined");
            const ttl = ticket.expiresAt - now();
            timer = later(start, Math.max(100, ttl - Math.min(30000, ttl / 2)));
          }).receive("error", () => retry(generation, { status: 401 }))
            .receive("timeout", () => retry(generation));
        };
        phase = "connect";
        socket.connect();
      } catch (error) { report("unavailable", phase); retry(generation, error); }
    }
    start();
    return {
      close,
      isReady,
      async sendMessage(payload) {
        const body = textPayload(payload);
        if (!body || !isReady()) return null;
        const result = await command("message.send", body);
        const message = result?.message;
        if (result?.accepted !== true || !message?.id || message.senderId !== deps.owner
          || message.receiverId !== body.receiverId || !/^[1-9][0-9]{0,18}$/.test(message.conversationSequence)) {
          throw failure("outcome_unknown");
        }
        return message;
      }
    };
  }
  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.phoenix = { createPhoenixTransport, canaryUrl, textPayload };
})();


// src/api/social-client.js
(() => {
  function createSocialApiClient(deps = {}) {
    const baseUrl = String(deps.baseUrl || "").replace(/\/+$/, "");
    const fetchJson = typeof deps.fetchJson === "function" ? deps.fetchJson : null;
    const createAuthHeaders = typeof deps.createAuthHeaders === "function" ? deps.createAuthHeaders : () => ({});

    function requireFetcher() {
      if (!fetchJson) throw new Error("Winga social API client requires fetchJson.");
    }
    function headers(json = false) {
      return { ...(json ? { "Content-Type": "application/json" } : {}), ...createAuthHeaders() };
    }
    async function loadFollows(options = {}) {
      requireFetcher();
      const query = new URLSearchParams({
        direction: String(options.direction || "following") === "followers" ? "followers" : "following",
        limit: String(Math.max(1, Math.min(Number(options.limit || 50) || 50, 100)))
      });
      if (String(options.cursor || "").trim()) query.set("cursor", String(options.cursor).trim());
      return fetchJson(`${baseUrl}/social/follows?${query}`, { headers: headers() });
    }
    async function loadFollowSuggestions(options = {}) {
      requireFetcher();
      const query = new URLSearchParams({
        limit: String(Math.max(1, Math.min(Number(options.limit || 12) || 12, 30)))
      });
      return fetchJson(`${baseUrl}/social/suggestions?${query}`, { headers: headers() });
    }
    async function loadBlocks(options = {}) {
      requireFetcher();
      const query = new URLSearchParams({
        limit: String(Math.max(1, Math.min(Number(options.limit || 30) || 30, 100)))
      });
      if (String(options.cursor || "").trim()) query.set("cursor", String(options.cursor).trim());
      return fetchJson(`${baseUrl}/social/blocks?${query}`, { headers: headers() });
    }
    async function loadSocialProfile(username, options = {}) {
      requireFetcher();
      const source = String(options.source || "").trim() === "follow" ? "?source=follow" : "";
      return fetchJson(`${baseUrl}/social/users/${encodeURIComponent(String(username || "").trim())}${source}`, { headers: headers() });
    }
    async function loadUserCollections(username, options = {}) {
      requireFetcher();
      const query = new URLSearchParams({
        limit: String(Math.max(1, Math.min(Number(options.limit || 12) || 12, 30)))
      });
      if (String(options.cursor || "").trim()) query.set("cursor", String(options.cursor).trim());
      return fetchJson(`${baseUrl}/social/users/${encodeURIComponent(String(username || "").trim())}/collections?${query}`, {
        headers: headers()
      });
    }
    async function createCollection(payload = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/social/collections`, {
        method: "POST",
        headers: headers(true),
        body: JSON.stringify(payload)
      });
    }
    async function updateCollection(collectionId, payload = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/social/collections/${encodeURIComponent(String(collectionId || "").trim())}`, {
        method: "PATCH",
        headers: headers(true),
        body: JSON.stringify(payload)
      });
    }
    async function setCollectionItem(collectionId, productId, options = {}) {
      requireFetcher();
      const remove = Boolean(options.remove);
      return fetchJson(`${baseUrl}/social/collections/${encodeURIComponent(String(collectionId || "").trim())}/items/${encodeURIComponent(String(productId || "").trim())}`, {
        method: remove ? "DELETE" : "PUT",
        headers: headers(true),
        ...(remove ? {} : { body: JSON.stringify({ position: options.position || 0, note: options.note || "" }) })
      });
    }
    async function setFollow(username, following, options = {}) {
      requireFetcher();
      const method = following ? "PUT" : "DELETE";
      const source = String(options.source || "").trim() === "suggested_follow" ? "suggested_follow" : "";
      return fetchJson(`${baseUrl}/social/follows/${encodeURIComponent(String(username || "").trim())}`, {
        method,
        headers: headers(following),
        ...(following ? { body: JSON.stringify(source ? { source } : {}) } : {})
      });
    }
    async function importLegacyFollows(usernames = []) {
      requireFetcher();
      return fetchJson(`${baseUrl}/social/follows/import`, {
        method: "POST",
        headers: headers(true),
        body: JSON.stringify({ usernames: Array.from(new Set(usernames)).slice(0, 100) })
      });
    }
    async function setBlock(username, blocked) {
      requireFetcher();
      const method = blocked ? "PUT" : "DELETE";
      return fetchJson(`${baseUrl}/social/blocks/${encodeURIComponent(String(username || "").trim())}`, {
        method,
        headers: headers(blocked),
        ...(blocked ? { body: "{}" } : {})
      });
    }
    async function setContentVisibility(contentType, contentId, visibility) {
      requireFetcher();
      const safeType = String(contentType || "").trim().toLowerCase();
      const safeContentId = String(contentId || "").trim();
      const safeVisibility = String(visibility || "").trim().toLowerCase();
      if (!["product", "reel", "review"].includes(safeType)) throw new Error("Invalid public content type.");
      if (!safeContentId) throw new Error("Content ID is required.");
      if (!["public", "followers", "private"].includes(safeVisibility)) throw new Error("Invalid content visibility.");
      return fetchJson(`${baseUrl}/social/content/${safeType}/${encodeURIComponent(safeContentId)}/visibility`, {
        method: "PATCH",
        headers: headers(true),
        body: JSON.stringify({ visibility: safeVisibility })
      });
    }
    return {
      loadFollows,
      loadFollowSuggestions,
      loadBlocks,
      loadSocialProfile,
      loadUserCollections,
      createCollection,
      updateCollection,
      setCollectionItem,
      setFollow,
      importLegacyFollows,
      setBlock,
      setContentVisibility
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.social = window.WingaModules.api.social || {};
  window.WingaModules.api.social.createSocialApiClient = createSocialApiClient;
})();


// src/api/commerce-client.js
(() => {
  function createCommerceApiClient(deps = {}) {
    const baseUrl = String(deps.baseUrl || "").replace(/\/+$/, "");
    const fetchJson = typeof deps.fetchJson === "function" ? deps.fetchJson : null;
    const createAuthHeaders = typeof deps.createAuthHeaders === "function" ? deps.createAuthHeaders : () => ({});

    function requireFetcher() {
      if (typeof fetchJson !== "function") {
        throw new Error("Winga commerce API client requires fetchJson.");
      }
    }

    function jsonHeaders() {
      return {
        "Content-Type": "application/json",
        ...createAuthHeaders()
      };
    }

    function authHeaders() {
      return {
        ...createAuthHeaders()
      };
    }

    async function loadPromotions() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/promotions`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function loadEligibleAds(placementCode) {
      requireFetcher();
      try {
        const data = await fetchJson(`${baseUrl}/ads/eligible?placement=${encodeURIComponent(placementCode || "")}`, {
          headers: authHeaders()
        });
        return Array.isArray(data) ? data : [];
      } catch (_error) {
        return [];
      }
    }

    async function loadAdAccount() {
      requireFetcher();
      try {
        return await fetchJson(`${baseUrl}/ads/account`, { headers: authHeaders() });
      } catch (error) {
        if (Number(error?.status || error?.statusCode || 0) === 404 || error?.code === "account_not_found") return null;
        throw error;
      }
    }

    async function createAdAccount(payload = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/ads/accounts`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify({ businessName: payload.businessName || "" })
      });
    }

    async function createPromotion(payload) {
      requireFetcher();
      const durationByType = { starter_day: 1, boost: 1, boost_3day: 3, category_boost: 3, featured: 7, growth_7day: 7, pin_top: 14, premium_14day: 14 };
      const quote = await fetchJson(`${baseUrl}/ads/quote`, { method: "POST", headers: jsonHeaders(),
        body: JSON.stringify({ placementCode: payload.placementCode || "HOME_FEED_SPONSORED", durationDays: durationByType[payload.type] || 1, startsAt: payload.startsAt || "" }) });
      const campaign = await fetchJson(`${baseUrl}/ads/campaigns`, { method: "POST", headers: jsonHeaders(),
        body: JSON.stringify({ productId: payload.productId, placementCode: quote.placementCode, durationDays: quote.durationDays,
          startsAt: quote.startsAt, destinationValue: payload.productId, headline: payload.headline || "",
          description: payload.description || "", ctaType: "VIEW_PRODUCT", targeting: payload.targeting || {} }) });
      await fetchJson(`${baseUrl}/ads/campaigns/${encodeURIComponent(campaign.id)}/payment`, {
        method: "POST", headers: { ...jsonHeaders(), "Idempotency-Key": `promotion-${campaign.id}-${payload.transactionReference}` },
        body: JSON.stringify({ transactionReference: payload.transactionReference, provider: payload.paymentProvider || "mobile_money" })
      });
      return { ...campaign, type: payload.type, transactionReference: payload.transactionReference };
    }

    async function loadAdminPromotions() {
      requireFetcher();
      const [legacyResult, adsResult] = await Promise.allSettled([
        fetchJson(`${baseUrl}/admin/promotions`, { headers: authHeaders() }),
        fetchJson(`${baseUrl}/admin/ads/campaigns`, { headers: authHeaders() })
      ]);
      const legacy = legacyResult.status === "fulfilled" && Array.isArray(legacyResult.value) ? legacyResult.value : [];
      const ads = adsResult.status === "fulfilled" && Array.isArray(adsResult.value)
        ? adsResult.value.map((campaign) => ({
          ...campaign, type: campaign.placementCode,
          status: String(campaign.campaignStatus || "").toLowerCase(),
          amountPaid: campaign.quotedPrice, sellerUsername: campaign.ownerUsername,
          transactionReference: campaign.transactionReference,
          startDate: campaign.startsAt, endDate: campaign.endsAt,
          paymentStatus: String(campaign.paymentStatus || "").toLowerCase()
        })) : [];
      return [...legacy, ...ads];
    }

    async function reviewPromotion(promotionId, payload) {
      requireFetcher();
      const isAdCampaign = String(promotionId || "").startsWith("adcmp-");
      return fetchJson(isAdCampaign
        ? `${baseUrl}/admin/ads/campaigns/${encodeURIComponent(promotionId)}/review`
        : `${baseUrl}/admin/promotions/${encodeURIComponent(promotionId)}/review`, {
        method: "PATCH", headers: jsonHeaders(),
        body: JSON.stringify(isAdCampaign ? {
          decision: payload?.status === "active" ? "APPROVED" : "REJECTED",
          reasonCode: payload?.status === "active" ? "" : (payload?.reasonCode || "OTHER"),
          explanation: payload?.explanation || ""
        } : (payload || {}))
      });
    }

    async function disablePromotion(promotionId) {
      requireFetcher();
      const isAdCampaign = String(promotionId || "").startsWith("adcmp-");
      return fetchJson(isAdCampaign
        ? `${baseUrl}/admin/ads/campaigns/${encodeURIComponent(promotionId)}/status`
        : `${baseUrl}/admin/promotions/${encodeURIComponent(promotionId)}/disable`, {
        method: "PATCH", headers: isAdCampaign ? jsonHeaders() : authHeaders(),
        ...(isAdCampaign ? { body: JSON.stringify({ status: "PAUSED" }) } : {})
      });
    }

    async function loadAdCampaigns() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/ads/campaigns`, { headers: authHeaders() });
      return Array.isArray(data) ? data : [];
    }

    async function loadAdCampaignReport(campaignId) {
      requireFetcher();
      return fetchJson(`${baseUrl}/ads/campaigns/${encodeURIComponent(campaignId)}/report`, {
        headers: authHeaders()
      });
    }

    async function recordAdEvent(payload) {
      requireFetcher();
      try {
        return await fetchJson(`${baseUrl}/ads/events`, {
          method: "POST",
          headers: jsonHeaders(),
          body: JSON.stringify(payload || {})
        });
      } catch (error) {
        return { accepted: false, code: "tracking_failed_open" };
      }
    }

    async function loadReviews(productId = "") {
      requireFetcher();
      const suffix = productId ? `?productId=${encodeURIComponent(productId)}` : "";
      return fetchJson(`${baseUrl}/reviews${suffix}`);
    }

    async function createReview(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/reviews`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function loadMyOrders() {
      requireFetcher();
      return fetchJson(`${baseUrl}/orders/mine`, {
        headers: authHeaders()
      });
    }

    async function createOrder(payload) {
      requireFetcher();
      const path = payload.reservationOrderId
        ? `/orders/${encodeURIComponent(payload.reservationOrderId)}/payment-reference`
        : payload.reserveBeforePayment ? "/orders/reservations" : "/orders";
      return fetchJson(`${baseUrl}${path}`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function updateOrderStatus(orderId, payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/orders/${encodeURIComponent(orderId)}/status`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    return {
      loadPromotions,
      loadEligibleAds,
      loadAdAccount,
      createAdAccount,
      createPromotion,
      loadAdminPromotions,
      reviewPromotion,
      disablePromotion,
      loadAdCampaigns,
      loadAdCampaignReport,
      recordAdEvent,
      loadReviews,
      createReview,
      loadMyOrders,
      createOrder,
      updateOrderStatus
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.commerce = window.WingaModules.api.commerce || {};
  window.WingaModules.api.commerce.createCommerceApiClient = createCommerceApiClient;
})();


// src/api/admin-client.js
(() => {
  function createAdminApiClient(deps = {}) {
    const baseUrl = String(deps.baseUrl || "").replace(/\/+$/, "");
    const fetchJson = typeof deps.fetchJson === "function" ? deps.fetchJson : null;
    const createAuthHeaders = typeof deps.createAuthHeaders === "function" ? deps.createAuthHeaders : () => ({});
    const resolveProductImages = typeof deps.resolveProductImages === "function" ? deps.resolveProductImages : (item) => item;
    const normalizeAppSettings = typeof deps.normalizeAppSettings === "function" ? deps.normalizeAppSettings : (settings) => settings || {};
    const defaultAppSettings = deps.defaultAppSettings || {};

    function requireFetcher() {
      if (typeof fetchJson !== "function") {
        throw new Error("Winga admin API client requires fetchJson.");
      }
    }

    function jsonHeaders() {
      return {
        "Content-Type": "application/json",
        ...createAuthHeaders()
      };
    }

    function authHeaders() {
      return {
        ...createAuthHeaders()
      };
    }

    function buildQuery(filters = {}, allowedKeys = []) {
      const params = new URLSearchParams();
      allowedKeys.forEach((key) => {
        if (filters[key]) {
          params.set(key, String(filters[key]));
        }
      });
      return params.toString() ? `?${params.toString()}` : "";
    }

    async function loadAdminOpsSummary() {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/ops/summary`, {
        headers: authHeaders()
      });
    }

    async function loadAdminUsers() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/admin/users`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function loadAdminProducts(status = "") {
      requireFetcher();
      const suffix = status ? `?status=${encodeURIComponent(status)}` : "";
      const data = await fetchJson(`${baseUrl}/admin/products${suffix}`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data.map(resolveProductImages) : [];
    }

    async function loadAdminVideos(status = "pending") {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/admin/media/videos?status=${encodeURIComponent(status)}&limit=50`, {
        headers: authHeaders()
      });
      return Array.isArray(data?.items) ? data.items : [];
    }

    async function moderateAdminVideo(providerId, payload = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/media/videos/${encodeURIComponent(providerId)}`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }
    async function loadAdminOrders(filters = {}) {
      requireFetcher();
      const suffix = buildQuery(filters, ["paymentStatus", "status"]);
      const data = await fetchJson(`${baseUrl}/admin/orders${suffix}`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data.map(resolveProductImages) : [];
    }

    async function loadAdminPayments(filters = {}) {
      requireFetcher();
      const suffix = buildQuery(filters, ["paymentStatus"]);
      const data = await fetchJson(`${baseUrl}/admin/payments${suffix}`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function loadPaymentReconciliations(filters = {}) {
      requireFetcher();
      const suffix = buildQuery(filters, ["status", "cursor", "limit"]);
      const data = await fetchJson(`${baseUrl}/admin/payment-reconciliations${suffix}`, {
        headers: authHeaders()
      });
      return {
        items: Array.isArray(data?.items) ? data.items : [],
        hasMore: Boolean(data?.hasMore),
        nextCursor: String(data?.nextCursor || "")
      };
    }

    async function updatePaymentReconciliation(caseId, payload = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/payment-reconciliations/${encodeURIComponent(caseId)}`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload || {})
      });
    }
    async function createReport(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/reports`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function loadAdminReports(filters = {}) {
      requireFetcher();
      const suffix = buildQuery(filters, ["status"]);
      const data = await fetchJson(`${baseUrl}/admin/reports${suffix}`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function createConversationReport(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/messages/reports`,{method:"POST",headers:jsonHeaders(),body:JSON.stringify(payload)});
    }
    async function readSharedReportEvidence(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/reports/evidence`,{method:"POST",headers:jsonHeaders(),body:JSON.stringify(payload)});
    }
    async function uploadReportFile(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/messages/reports/files`,{method:'POST',headers:jsonHeaders(),body:JSON.stringify(payload)});
    }
    async function readSharedReportFile(payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/reports/files`,{method:'POST',headers:jsonHeaders(),body:JSON.stringify(payload)});
    }

    async function reviewReport(reportId, payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/reports/${encodeURIComponent(reportId)}`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function loadAdminSettings() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/admin/settings`, {
        headers: authHeaders()
      });
      return normalizeAppSettings(data || defaultAppSettings);
    }

    async function updateAdminSettings(payload) {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/admin/settings`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload || {})
      });
      return normalizeAppSettings(data || defaultAppSettings);
    }

    async function loadAdminMessages() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/admin/messages`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    async function reviewAdminMessage(conversationId, payload = {}) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/messages/${encodeURIComponent(conversationId)}/review`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload || {})
      });
    }

    async function loadAdminUserInvestigation(username, payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/users/${encodeURIComponent(username)}/investigation`, {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify(payload || {})
      });
    }

    async function moderateUser(username, payload) {
      requireFetcher();
      return fetchJson(`${baseUrl}/admin/users/${encodeURIComponent(username)}/moderation`, {
        method: "PATCH",
        headers: jsonHeaders(),
        body: JSON.stringify(payload)
      });
    }

    async function loadModerationActions() {
      requireFetcher();
      const data = await fetchJson(`${baseUrl}/admin/moderation-actions`, {
        headers: authHeaders()
      });
      return Array.isArray(data) ? data : [];
    }

    return {
      loadAdminOpsSummary,
      loadAdminUsers,
      loadAdminProducts,
      loadAdminVideos,
      moderateAdminVideo,
      loadAdminOrders,
      loadAdminPayments,
      loadPaymentReconciliations,
      updatePaymentReconciliation,
      createReport,
      createConversationReport,readSharedReportEvidence,uploadReportFile,readSharedReportFile,
      loadAdminReports,
      reviewReport,
      loadAdminSettings,
      updateAdminSettings,
      loadAdminMessages,
      reviewAdminMessage,
      loadAdminUserInvestigation,
      moderateUser,
      loadModerationActions
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.admin = window.WingaModules.api.admin || {};
  window.WingaModules.api.admin.createAdminApiClient = createAdminApiClient;
})();


// src/api/intelligence-client.js
(() => {
  function createIntelligenceApiClient(deps = {}) {
    const baseUrl = String(deps.baseUrl || "").replace(/\/+$/, "");
    const fetchJson = typeof deps.fetchJson === "function" ? deps.fetchJson : null;
    const createAuthHeaders = typeof deps.createAuthHeaders === "function" ? deps.createAuthHeaders : () => ({});
    const getConfig = typeof deps.getConfig === "function" ? deps.getConfig : () => ({});
    const schedule = typeof deps.schedule === "function" ? deps.schedule : (callback, delayMs) => setTimeout(callback, delayMs);
    const cancelSchedule = typeof deps.cancelSchedule === "function" ? deps.cancelSchedule : (timer) => clearTimeout(timer);
    const lifecycleTarget = deps.lifecycleTarget || (typeof window !== "undefined" ? window : null);
    const maxBatchSize = Math.max(1, Math.min(25, Number(deps.maxClientEventBatchSize || 20) || 20));
    const maxBufferedEvents = Math.max(maxBatchSize, Math.min(200, Number(deps.maxBufferedClientEvents || 100) || 100));
    const flushDelayMs = Math.max(100, Math.min(5000, Number(deps.clientEventFlushDelayMs || 750) || 750));
    const clientEventQueue = [];
    let clientEventFlushTimer = null;
    let clientEventFlushPromise = null;

    function requireFetcher() {
      if (typeof fetchJson !== "function") {
        throw new Error("Winga intelligence API client requires fetchJson.");
      }
    }

    function jsonHeaders() {
      return {
        "Content-Type": "application/json",
        ...createAuthHeaders()
      };
    }

    function scheduleClientEventFlush(delayMs = flushDelayMs) {
      if (clientEventFlushTimer !== null || clientEventFlushPromise || !clientEventQueue.length) return;
      clientEventFlushTimer = schedule(() => {
        clientEventFlushTimer = null;
        void flushClientEvents();
      }, Math.max(0, Number(delayMs) || 0));
    }

    async function flushClientEvents(options = {}) {
      requireFetcher();
      if (clientEventFlushPromise) return clientEventFlushPromise;
      if (getConfig()?.enableClientEventLogging === false) {
        clientEventQueue.length = 0;
        return null;
      }
      if (!clientEventQueue.length) return null;
      if (clientEventFlushTimer !== null) {
        cancelSchedule(clientEventFlushTimer);
        clientEventFlushTimer = null;
      }
      const events = clientEventQueue.splice(0, maxBatchSize);
      clientEventFlushPromise = fetchJson(baseUrl + "/client-events", {
        method: "POST",
        headers: jsonHeaders(),
        body: JSON.stringify({ events }),
        keepalive: options.keepalive === true,
        timeoutMs: 15000
      })
        .catch(() => {
          // Telemetry must never block the marketplace path.
          return null;
        })
        .finally(() => {
          clientEventFlushPromise = null;
          if (clientEventQueue.length) scheduleClientEventFlush(0);
        });
      return clientEventFlushPromise;
    }

    async function logClientEvent(event) {
      requireFetcher();
      if (getConfig()?.enableClientEventLogging === false) return null;
      clientEventQueue.push(event);
      while (clientEventQueue.length > maxBufferedEvents) clientEventQueue.shift();
      if (event?.level === "error" || clientEventQueue.length >= maxBatchSize) {
        return flushClientEvents();
      }
      scheduleClientEventFlush();
      return null;
    }

    lifecycleTarget?.addEventListener?.("pagehide", () => {
      void flushClientEvents({ keepalive: true });
    });
    async function submitSearchDemandEvents(events = []) {
      requireFetcher();
      const batch = Array.isArray(events) ? events.filter(Boolean).slice(-25) : [];
      if (!batch.length) {
        return { ok: true, accepted: 0, inserted: 0 };
      }
      try {
        return await fetchJson(`${baseUrl}/search-demand`, {
          method: "POST",
          headers: jsonHeaders(),
          body: JSON.stringify({ events: batch })
        });
      } catch (error) {
        return {
          ok: false,
          accepted: 0,
          inserted: 0,
          error: error?.message || "search-demand unavailable"
        };
      }
    }

    return {
      logClientEvent,
      flushClientEvents,
      submitSearchDemandEvents
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.intelligence = window.WingaModules.api.intelligence || {};
  window.WingaModules.api.intelligence.createIntelligenceApiClient = createIntelligenceApiClient;
})();


// src/api/admin-tools.js
(() => {
  function createAdminDataTools() {
    function summarizeAdminMessageThreads(messages = [], users = [], reports = []) {
      const userMap = new Map((Array.isArray(users) ? users : []).map((user) => {
        const username = String(user?.username || "").trim();
        return [username, user];
      }));
      const threadMap = new Map();
      (Array.isArray(messages) ? messages : []).forEach((message) => {
        const conversationId = String(message?.conversationId || "").trim() || [message?.senderId, message?.receiverId].filter(Boolean).sort().join("::") + `::${message?.productId || ""}`;
        const existing = threadMap.get(conversationId) || {
          conversationId,
          senderId: String(message?.senderId || "").trim(),
          receiverId: String(message?.receiverId || "").trim(),
          senderName: userMap.get(String(message?.senderId || "").trim())?.fullName || String(message?.senderId || "").trim(),
          receiverName: userMap.get(String(message?.receiverId || "").trim())?.fullName || String(message?.receiverId || "").trim(),
          productId: String(message?.productId || "").trim(),
          productName: String(message?.productName || "").trim(),
          messageType: String(message?.messageType || "text").trim(),
          messageCount: 0,
          unreadCount: 0,
          lastMessageAt: "",
          lastMessagePreview: "",
          reportCount: 0
        };
        existing.messageCount += 1;
        if (!message?.isRead) {
          existing.unreadCount += 1;
        }
        const nextTime = new Date(message?.timestamp || message?.createdAt || 0).getTime();
        const currentTime = new Date(existing.lastMessageAt || 0).getTime();
        if (!existing.lastMessageAt || nextTime >= currentTime) {
          existing.lastMessageAt = String(message?.timestamp || message?.createdAt || "");
          existing.lastMessagePreview = String(message?.message || "").trim().slice(0, 160);
          existing.messageType = String(message?.messageType || "text").trim() || existing.messageType;
          existing.productId = String(message?.productId || existing.productId || "").trim();
          existing.productName = String(message?.productName || existing.productName || "").trim();
          existing.senderId = String(message?.senderId || existing.senderId || "").trim();
          existing.receiverId = String(message?.receiverId || existing.receiverId || "").trim();
          existing.senderName = userMap.get(existing.senderId)?.fullName || existing.senderId;
          existing.receiverName = userMap.get(existing.receiverId)?.fullName || existing.receiverId;
        }
        threadMap.set(conversationId, existing);
      });

      const reportList = Array.isArray(reports) ? reports : [];
      return Array.from(threadMap.values())
        .map((thread) => {
          const relatedReports = reportList.filter((report) =>
            String(report?.targetUserId || "") === thread.senderId
            || String(report?.targetUserId || "") === thread.receiverId
            || String(report?.targetProductId || "") === thread.productId
            || /message|chat|conversation|abuse|fraud/i.test(`${report?.reason || ""} ${report?.description || ""}`)
          );
          return {
            ...thread,
            reportCount: relatedReports.length,
            hasReportedContent: relatedReports.length > 0
          };
        })
        .sort((first, second) => new Date(second.lastMessageAt || 0).getTime() - new Date(first.lastMessageAt || 0).getTime());
    }

    function buildAdminMessageReviewDetails(messages = [], users = [], reports = [], conversationId = "", reason = "", reviewer = "") {
      const normalizedConversationId = String(conversationId || "").trim();
      const normalizedMessages = (Array.isArray(messages) ? messages : [])
        .filter((message) => String(message?.conversationId || "").trim() === normalizedConversationId)
        .map((message) => ({
          ...message,
          senderId: String(message?.senderId || "").trim(),
          receiverId: String(message?.receiverId || "").trim(),
          productId: String(message?.productId || "").trim(),
          productName: String(message?.productName || "").trim(),
          messageType: String(message?.messageType || "text").trim(),
          message: String(message?.message || "").trim()
        }))
        .sort((first, second) => new Date(first.timestamp || first.createdAt || 0).getTime() - new Date(second.timestamp || second.createdAt || 0).getTime());

      if (!normalizedMessages.length) {
        return null;
      }

      const thread = summarizeAdminMessageThreads(normalizedMessages, users, reports).find((item) => item.conversationId === normalizedConversationId) || null;
      const lastMessage = normalizedMessages[normalizedMessages.length - 1];
      const userMap = new Map((Array.isArray(users) ? users : []).map((user) => [String(user?.username || "").trim(), user]));
      const sender = userMap.get(lastMessage.senderId) || null;
      const receiver = userMap.get(lastMessage.receiverId) || null;

      return {
        conversationId: normalizedConversationId,
        reason: String(reason || "").trim(),
        reviewedBy: String(reviewer || "").trim(),
        reviewedAt: new Date().toISOString(),
        participants: {
          sender: sender ? {
            username: sender.username || lastMessage.senderId,
            fullName: sender.fullName || sender.username || lastMessage.senderId,
            role: sender.role || ""
          } : {
            username: lastMessage.senderId,
            fullName: lastMessage.senderId,
            role: ""
          },
          receiver: receiver ? {
            username: receiver.username || lastMessage.receiverId,
            fullName: receiver.fullName || receiver.username || lastMessage.receiverId,
            role: receiver.role || ""
          } : {
            username: lastMessage.receiverId,
            fullName: lastMessage.receiverId,
            role: ""
          }
        },
        summary: thread || {
          conversationId: normalizedConversationId,
          senderId: lastMessage.senderId,
          receiverId: lastMessage.receiverId,
          productId: lastMessage.productId || "",
          productName: lastMessage.productName || "",
          messageType: lastMessage.messageType || "text",
          messageCount: normalizedMessages.length,
          unreadCount: normalizedMessages.filter((message) => !message.isRead).length,
          lastMessageAt: lastMessage.timestamp || lastMessage.createdAt || "",
          lastMessagePreview: String(lastMessage.message || "").trim().slice(0, 160),
          reportCount: 0,
          hasReportedContent: false
        },
        messages: normalizedMessages.map((message) => ({
          id: message.id,
          senderId: message.senderId,
          receiverId: message.receiverId,
          productId: message.productId || "",
          productName: message.productName || "",
          messageType: message.messageType || "text",
          message: message.message || "",
          timestamp: message.timestamp || "",
          createdAt: message.createdAt || "",
          updatedAt: message.updatedAt || "",
          deliveredAt: message.deliveredAt || "",
          readAt: message.readAt || "",
          isDelivered: Boolean(message.isDelivered),
          isRead: Boolean(message.isRead)
        }))
      };
    }

    return {
      summarizeAdminMessageThreads,
      buildAdminMessageReviewDetails
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.adminTools = window.WingaModules.api.adminTools || {};
  window.WingaModules.api.adminTools.createAdminDataTools = createAdminDataTools;
})();


// src/api/storage-tools.js
(() => {
  function createStorageTools(deps = {}) {
    const getStorage = typeof deps.getStorage === "function" ? deps.getStorage : () => localStorage;

    function safeStorageGet(key) {
      try {
        return getStorage().getItem(key);
      } catch (_error) {
        return null;
      }
    }

    function safeStorageSet(key, value) {
      try {
        getStorage().setItem(key, value);
        return true;
      } catch (_error) {
        return false;
      }
    }

    function setStorageOrThrow(key, value, label = "data za Winga") {
      try {
        getStorage().setItem(key, value);
        return true;
      } catch (error) {
        const quotaExceeded = error?.name === "QuotaExceededError"
          || error?.code === 22
          || error?.code === 1014
          || /quota|storage|space/i.test(String(error?.message || ""));
        if (quotaExceeded) {
          throw new Error(`${label} zimezidi nafasi ya browser/simu. Punguza idadi au ukubwa wa picha kisha ujaribu tena.`);
        }
        throw new Error(`Imeshindikana kuhifadhi ${label} kwenye browser hii. Jaribu tena au fungua app upya.`);
      }
    }

    function safeStorageRemove(key) {
      try {
        getStorage().removeItem(key);
      } catch (_error) {
        // Ignore storage removal failures and continue with in-memory flow.
      }
    }

    function readStoredJson(key, fallbackValue) {
      const raw = safeStorageGet(key);
      if (!raw) {
        return fallbackValue;
      }
      try {
        return JSON.parse(raw);
      } catch (_error) {
        return fallbackValue;
      }
    }

    return {
      safeStorageGet,
      safeStorageSet,
      setStorageOrThrow,
      safeStorageRemove,
      readStoredJson
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.storageTools = window.WingaModules.api.storageTools || {};
  window.WingaModules.api.storageTools.createStorageTools = createStorageTools;
})();


// src/api/offline-queue.js
(() => {
  function createOfflineQueueTools(deps = {}) {
    const queueKeyPrefix = String(deps.queueKeyPrefix || "winga-offline-action-queue");
    const readSession = typeof deps.readSession === "function" ? deps.readSession : () => null;
    const safeStorageGet = typeof deps.safeStorageGet === "function" ? deps.safeStorageGet : () => null;
    const safeStorageSet = typeof deps.safeStorageSet === "function" ? deps.safeStorageSet : () => false;
    const safeStorageRemove = typeof deps.safeStorageRemove === "function" ? deps.safeStorageRemove : () => {};
    const clone = typeof deps.clone === "function" ? deps.clone : (value) => JSON.parse(JSON.stringify(value));
    const getDefaultAdapter = typeof deps.getDefaultAdapter === "function" ? deps.getDefaultAdapter : () => null;
    const getNavigator = typeof deps.getNavigator === "function" ? deps.getNavigator : () => globalThis.navigator;
    const dispatchEvent = typeof deps.dispatchEvent === "function" ? deps.dispatchEvent : () => {};
    const activeFlushes = new Map();
    const activeMessageSends = new Set();

    function getOfflineActionQueueStorageKey(session = readSession()) {
      const username = String(session?.username || "").trim();
      if (!username) {
        return "";
      }
      return `${queueKeyPrefix}:${username}`;
    }

    function readOfflineActionQueue(session = readSession()) {
      const storageKey = getOfflineActionQueueStorageKey(session);
      if (!storageKey) {
        return [];
      }
      const raw = safeStorageGet(storageKey);
      if (!raw) {
        return [];
      }
      try {
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) throw new Error();
        return parsed.filter(Boolean);
      } catch (_error) {
        throw new Error("Saved message queue could not be read. It has not been replaced.");
      }
    }

    function saveOfflineActionQueue(queue = [], session = readSession()) {
      const storageKey = getOfflineActionQueueStorageKey(session);
      if (!storageKey) {
        return;
      }
      if (!Array.isArray(queue) || !queue.length) {
        safeStorageRemove(storageKey);
        if (safeStorageGet(storageKey)) {
          throw new Error("Saved message queue could not be updated on this device.");
        }
        return;
      }
      if (safeStorageSet(storageKey, JSON.stringify(queue)) !== true) {
        throw new Error("Message could not be saved on this device. Keep your draft and try again.");
      }
    }

    function isLikelyOfflineActionError(error) {
      const status = Number(error?.status || 0);
      if (status) return status === 408 || status === 429 || status >= 500;
      if (error?.retryable === true) return true;
      const message = String(error?.message || "").toLowerCase();
      return Boolean(
        error?.name === "TypeError"
        || message.includes("failed to fetch")
        || message.includes("network")
        || message.includes("offline")
        || message.includes("fetch")
        || message.includes("request took too long")
      );
    }

    async function mutateOfflineActionQueue(session, change, requireOwner = false) {
      const owner = String(session?.username || "").trim();
      const run = () => {
        if (requireOwner && String(readSession()?.username || "").trim() !== owner) {
          throw new Error("Account changed before the message could be saved.");
        }
        const { queue, result } = change(readOfflineActionQueue(session));
        saveOfflineActionQueue(queue, session);
        return result;
      };
      // Keep storage critical sections separate from the network send lock so
      // another tab can durably enqueue while a request is still in flight.
      const locks = getNavigator()?.locks;
      return locks?.request
        ? locks.request(`winga-offline-queue:${getOfflineActionQueueStorageKey(session)}`, run)
        : run();
    }

    function updateQueuedItem(session, id, change) {
      return mutateOfflineActionQueue(session, queue => ({
        queue: queue.flatMap(item => item.id === id ? change(item) : [item])
      }));
    }

    async function queueOfflineMessageAction(payload, session = readSession()) {
      const username = String(session?.username || "").trim();
      if (!username) {
        throw new Error("Ingia kwanza kabla ya kutuma ujumbe.");
      }
      if (!payload?.receiverId || (!payload?.message && !(Array.isArray(payload?.productItems) && payload.productItems.length))) {
        throw new Error("Receiver na ujumbe au bidhaa vinahitajika.");
      }

      session = { username };
      const createdAt = new Date().toISOString();
      const queuedAction = {
        id: `offline-msg-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: "sendMessage",
        payload: clone(payload),
        createdAt,
        attempts: 0
      };
      const count = await mutateOfflineActionQueue(session, queue => ({
        queue: [...queue, queuedAction], result: queue.length + 1
      }), true);
      dispatchEvent("winga:offline-actions-updated", {
        count,
        username
      });
      return {
        id: queuedAction.id,
        senderId: username,
        receiverId: payload.receiverId,
        messageType: payload.messageType || (Array.isArray(payload.productItems) && payload.productItems.length > 1 ? "product_inquiry" : Array.isArray(payload.productItems) && payload.productItems.length === 1 ? "product_reference" : "text"),
        productId: payload.productId || "",
        productName: payload.productName || "",
        productItems: Array.isArray(payload.productItems) ? payload.productItems : [],
        replyToMessageId: payload.replyToMessageId || "",
        message: payload.message || "",
        timestamp: createdAt,
        createdAt,
        updatedAt: createdAt,
        deliveredAt: "",
        readAt: "",
        isDelivered: false,
        isRead: false,
        isQueued: true
      };
    }

    async function sendPersistedMessage(payload, adapter, session = readSession()) {
      if (!payload?.clientMessageId || typeof adapter?.sendMessage !== "function") {
        throw new Error("Durable message retry support is required.");
      }
      session = { username: String(session?.username || "").trim() };
      const queued = await queueOfflineMessageAction(payload, session);
      const owner = session.username;
      activeMessageSends.add(queued.id);
      const updateItem = change => updateQueuedItem(session, queued.id, change);
      const run = async () => {
        if (readSession()?.username !== owner || getNavigator()?.onLine === false) return queued;
        let result;
        try {
          result = await adapter.sendMessage(payload);
          if (!result?.id || result.isQueued || result.skipped) {
            throw Object.assign(new Error("Message acceptance was not confirmed."), { retryable: true });
          }
        } catch (error) {
          const retryable = isLikelyOfflineActionError(error);
          await updateItem(item => [{ ...item, attempts: Number(item.attempts || 0) + 1,
            status: retryable ? "QUEUED" : "FAILED",
            lastErrorCode: String(error?.code || "message_send_failed").slice(0, 80) }]);
          if (retryable) return queued;
          throw error;
        }
        // An accepted send stays successful even if local cleanup fails. Its ID
        // remains replay-safe when the retained entry is reconciled later.
        try { await updateItem(() => []); } catch (_error) { /* Preserve accepted result. */ }
        return result;
      };
      try {
        const locks = getNavigator()?.locks;
        return await (locks?.request ? locks.request(`winga-offline-send:${owner}`, run) : run());
      } finally {
        activeMessageSends.delete(queued.id);
      }
    }

    function getPendingMessages(receiverId) {
      return readOfflineActionQueue().filter(item => item.type === "sendMessage"
        && item.payload?.receiverId === receiverId && !activeMessageSends.has(item.id));
    }

    async function flushOfflineActionQueue(adapter = null, retryId = "") {
      const activeAdapter = adapter || getDefaultAdapter();
      if (!activeAdapter || typeof activeAdapter.sendMessage !== "function") {
        return 0;
      }
      const session = { username: String(readSession()?.username || "").trim() };
      if (!session?.username || getNavigator()?.onLine === false) {
        return 0;
      }

      const owner = session.username;
      const active = activeFlushes.get(owner);
      if (active) {
        if (!retryId || active.retryId === retryId) return active.promise;
        await active.promise;
        if (readSession()?.username !== owner || active.attemptedIds.has(retryId)) return 0;
        return flushOfflineActionQueue(activeAdapter, retryId);
      }
      const operation = { retryId, attemptedIds: new Set(), promise: null };
      const run = async () => {
        const queue = readOfflineActionQueue(session);
        let flushedCount = 0;
        let failedCount = 0;
        const updateItem = (id, change) => updateQueuedItem(session, id, change);
        for (const item of queue) {
          if (readSession()?.username !== owner || getNavigator()?.onLine === false) break;
          if (!item || item.type !== "sendMessage" || activeMessageSends.has(item.id)) continue;
          if (retryId ? item.id !== retryId : item.status === "FAILED") continue;
          operation.attemptedIds.add(item.id);
          try {
            const payload = activeAdapter.prepareMessage ? await activeAdapter.prepareMessage(item.payload) : item.payload;
            await updateItem(item.id, current => [{ ...current, payload, status: "QUEUED" }]);
            if (readSession()?.username !== owner || getNavigator()?.onLine === false) break;
            const result = await activeAdapter.sendMessage(payload);
            if (!result?.id || result.isQueued || result.skipped) {
              throw Object.assign(new Error("Message acceptance was not confirmed."), { retryable: true });
            }
          } catch (error) {
            const retryable = isLikelyOfflineActionError(error);
            await updateItem(item.id, current => [{
              ...current, attempts: Number(current.attempts || 0) + 1,
              status: retryable ? "QUEUED" : "FAILED",
              lastErrorCode: String(error?.code || "message_send_failed").slice(0, 80)
            }]);
            if (!retryable) failedCount += 1;
            if (retryable || readSession()?.username !== owner) break;
            continue;
          }
          // Cleanup failure cannot turn a confirmed acceptance into rejection.
          try { await updateItem(item.id, () => []); } catch (_error) { /* Retry retains the same logical ID. */ }
          flushedCount += 1;
        }
        const remaining = readOfflineActionQueue(session).length;
        if (flushedCount || failedCount) dispatchEvent("winga:offline-actions-flushed", {
          count: flushedCount, remaining, failed: failedCount, username: owner
        });
        return flushedCount;
      };
      const locks = getNavigator()?.locks;
      const flush = locks?.request ? locks.request(`winga-offline-send:${owner}`, run) : run();
      operation.promise = flush;
      activeFlushes.set(owner, operation);
      try { return await flush; } finally { activeFlushes.delete(owner); }
    }

    return {
      getOfflineActionQueueStorageKey,
      readOfflineActionQueue,
      isLikelyOfflineActionError,
      queueOfflineMessageAction,
      sendPersistedMessage,
      getPendingMessages,
      flushOfflineActionQueue
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.offlineQueue = window.WingaModules.api.offlineQueue || {};
  window.WingaModules.api.offlineQueue.createOfflineQueueTools = createOfflineQueueTools;
})();


// src/api/settings-tools.js
(() => {
  const DEFAULT_APP_SETTINGS = Object.freeze({
    heroSectionVisible: false,
    standaloneShowcaseVisible: false,
    splashScreenVisible: true,
    sessionExpiryMinutes: 120,
    cachePolicy: "balanced",
    requireExplicitSignOut: true,
    messageReviewRequiresReason: true
  });

  function normalizeAppSettings(settings = {}) {
    const source = settings && typeof settings === "object" && !Array.isArray(settings) ? settings : {};
    const sessionExpiryMinutes = Number.parseInt(source.sessionExpiryMinutes, 10);
    const cachePolicy = String(source.cachePolicy || "").trim().toLowerCase();
    return {
      heroSectionVisible: typeof source.heroSectionVisible === "boolean" ? source.heroSectionVisible : DEFAULT_APP_SETTINGS.heroSectionVisible,
      standaloneShowcaseVisible: typeof source.standaloneShowcaseVisible === "boolean" ? source.standaloneShowcaseVisible : DEFAULT_APP_SETTINGS.standaloneShowcaseVisible,
      splashScreenVisible: typeof source.splashScreenVisible === "boolean" ? source.splashScreenVisible : DEFAULT_APP_SETTINGS.splashScreenVisible,
      sessionExpiryMinutes: Number.isFinite(sessionExpiryMinutes) ? Math.max(15, Math.min(1440, sessionExpiryMinutes)) : DEFAULT_APP_SETTINGS.sessionExpiryMinutes,
      cachePolicy: ["balanced", "cache-first", "network-first"].includes(cachePolicy) ? cachePolicy : DEFAULT_APP_SETTINGS.cachePolicy,
      requireExplicitSignOut: source.requireExplicitSignOut !== false,
      messageReviewRequiresReason: source.messageReviewRequiresReason !== false,
      updatedAt: String(source.updatedAt || "").trim(),
      updatedBy: String(source.updatedBy || "").trim()
    };
  }

  function createSettingsTools() {
    return {
      DEFAULT_APP_SETTINGS,
      normalizeAppSettings
    };
  }

  window.WingaModules = window.WingaModules || {};
  window.WingaModules.api = window.WingaModules.api || {};
  window.WingaModules.api.settingsTools = window.WingaModules.api.settingsTools || {};
  window.WingaModules.api.settingsTools.createSettingsTools = createSettingsTools;
})();


