          startupTimer: 0,
          speculative: false,
          retryWhenVisible: false,
          programmaticallyPaused: false,
          hls: null,
          readyPromise: null,
          resolveReady: null,
          prewarmQueued: false,
          nearViewport: false,
          inPlaybackViewport: false,
          intersectionRatio: 0,
          viewportDistance: Number.MAX_SAFE_INTEGER,
          bufferStartedAt: 0,
          recoveryTimer: 0,
          recoveryStartedAt: 0,
          networkRecoveryAttempts: 0,
          mediaRecoveryAttempts: 0,
          awaitingNetwork: false,
          playbackProfile: "",
          prewarmTarget: null,
          impressionReported: false,
          watchStartedAt: 0,
          watchedMs: 0,
          bufferedMs: 0,
          playCount: 0,
          completionCount: 0,
          replayCount: 0,
          pendingPlaybackCycle: false,
          completionReportedForLoop: false,
          lastCurrentTime: 0,
          lastMuted: true,
          audioRequested: false,
          summaryGeneration: -1
